INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('2740f4ce-c50e-5c6c-8b6d-bc235ef59d33','a0000000-0000-4000-8000-000000000052','Блок 1. The verb ''to be''',1,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('43406f90-6e20-528f-a0d8-ff484c73007a','2740f4ce-c50e-5c6c-8b6d-bc235ef59d33','The verb ''to be''',0,'LESSON',70,$j$[{"type": "rule", "text": "The verb to be has the forms am, is, are. Long forms (am, is, are) are used in writing; short forms ('m, 's, 're) are used in speaking."}, {"type": "rule", "text": "In short answers we do not repeat the whole question: Yes/No + subject pronoun + verb (am/'m not, is/isn't, are/aren't). Positive short answers use the long form (Yes, I am); negative short answers use the short form (No, he isn't)."}, {"type": "examples", "items": ["Helena is from Sweden. She is seventeen years old.", "Is she your friend? Yes, she is.", "Are you tired? Yes, I am.", "Is he your teacher? No, he isn't."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('79b11ff3-38e5-5b14-bb1b-918f84d6dd92','43406f90-6e20-528f-a0d8-ff484c73007a',0,'FILL_BLANK','Заполните пропуски правильной формой глагола to be (am/is/are).',$j${"items": [{"before": "Hi, my name is Alice. I", "after": "a music student."}, {"before": "I", "after": "seventeen years old."}, {"before": "My favourite instrument", "after": "the violin."}, {"before": "This", "after": "my best friend Kate."}, {"before": "She", "after": "sixteen years old."}, {"before": "We", "after": "in the same class at school."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('79b11ff3-38e5-5b14-bb1b-918f84d6dd92',$j${"items": [{"accept": ["am", "'m"]}, {"accept": ["am", "'m"]}, {"accept": ["is", "'s"]}, {"accept": ["is", "'s"]}, {"accept": ["is", "'s"]}, {"accept": ["are", "'re"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('914ad9f2-6c86-5596-8b51-f959522cda58','43406f90-6e20-528f-a0d8-ff484c73007a',1,'FILL_BLANK','Дополните короткие ответы правильной формой глагола to be.',$j${"items": [{"before": "Are you a footballer? No, I", "after": "."}, {"before": "Is that a DVD player? No, it", "after": "."}, {"before": "Are they sunglasses? No, they", "after": "."}, {"before": "Is Frank from Germany? No, he", "after": "."}, {"before": "Are you from Portugal? Yes, I", "after": "."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('914ad9f2-6c86-5596-8b51-f959522cda58',$j${"items": [{"accept": ["'m not", "am not"]}, {"accept": ["isn't", "is not"]}, {"accept": ["aren't", "are not"]}, {"accept": ["isn't", "is not"]}, {"accept": ["am"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9d060c92-d721-5d2b-8e9a-30a2310af117','43406f90-6e20-528f-a0d8-ff484c73007a',2,'FILL_BLANK','Заполните пропуски правильной формой глагола to be (текст Хуана).',$j${"items": [{"before": "I", "after": "eleven years old and I am from Spain."}, {"before": "My brother Pedro", "after": "thirteen years old."}, {"before": "My parents", "after": "Carlos and Maria."}, {"before": "They", "after": "primary school teachers."}, {"before": "We", "after": "in the same school, but not in the same class."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9d060c92-d721-5d2b-8e9a-30a2310af117',$j${"items": [{"accept": ["am", "'m"]}, {"accept": ["is", "'s"]}, {"accept": ["are", "'re"]}, {"accept": ["are", "'re"]}, {"accept": ["are", "'re"]}]}$j$::jsonb,'');
INSERT INTO "LessonUnit" (id,"moduleId",title,subtitle,"orderIndex",kind,"passThreshold",intro) VALUES ('fa1d36f4-5e58-5cd0-b151-1a7a4fd0e681','2740f4ce-c50e-5c6c-8b6d-bc235ef59d33','Тест блока: The verb ''to be''','Ответь верно минимум на 70%, чтобы открыть следующий блок',1,'TEST',70,'[]'::jsonb);
