INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('5b4f0ff7-bae0-5cd2-8338-aa50dd5aa654','a0000000-0000-4000-8000-000000000052','Блок 2. The verb ''have got''',2,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f3759675-9c2c-5255-afed-228a0b69638d','5b4f0ff7-bae0-5cd2-8338-aa50dd5aa654','The verb ''have got''',0,'LESSON',70,$j$[{"type": "rule", "text": "We use have got to show possession, to describe people/animals/things, and to talk about relationships. Forms: I/you/we/they have got ('ve got); he/she/it has got ('s got). Negative: haven't got / hasn't got."}, {"type": "rule", "text": "Questions: Have I/you/we/they got...? Has he/she/it got...? In short answers we do NOT use got: Yes, I have. / No, she hasn't."}, {"type": "examples", "items": ["We've got two goldfish and a cat.", "Eagles have got big wings.", "Have you got a twin brother?", "I've got a headache."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('17ec1f9f-b087-5f75-8f75-655c7b1b2598','f3759675-9c2c-5255-afed-228a0b69638d',0,'FILL_BLANK','Заполните пропуски: have, haven''t, has или hasn''t.',$j${"items": [{"before": "Have Barry and Vicky got a TV? Yes, they", "after": "."}, {"before": "Have you got a big garden? No, I", "after": "."}, {"before": "Has Sarah got an evening dress? Yes, she", "after": "."}, {"before": "Has your mum got a laptop? No, she", "after": "."}, {"before": "Have you got a cold? Yes, I", "after": ". I feel terrible."}, {"before": "Has your dad got a red car? No, he", "after": ". His car is blue."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('17ec1f9f-b087-5f75-8f75-655c7b1b2598',$j${"items": [{"accept": ["have"]}, {"accept": ["haven't"]}, {"accept": ["has"]}, {"accept": ["hasn't"]}, {"accept": ["have"]}, {"accept": ["hasn't"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a3e359ea-e4fc-5e29-8f3f-dc070cc894e7','f3759675-9c2c-5255-afed-228a0b69638d',1,'FILL_BLANK','Заполните пропуски правильной формой be или have got (текст Мелиссы).',$j${"items": [{"before": "My mum is Helen and she", "after": "thirty-nine years old."}, {"before": "She", "after": "a secretary."}, {"before": "My dad Pablo is forty-five and he", "after": "an English teacher."}, {"before": "He", "after": "lots of books."}, {"before": "We", "after": "a cat, too."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('a3e359ea-e4fc-5e29-8f3f-dc070cc894e7',$j${"items": [{"accept": ["is", "'s"]}, {"accept": ["is", "'s"]}, {"accept": ["is", "'s"]}, {"accept": ["has got", "'s got"]}, {"accept": ["have got", "'ve got"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('073858a2-4821-53c6-8368-aad09c323cd1','f3759675-9c2c-5255-afed-228a0b69638d',2,'FILL_BLANK','Дополните диалог формами be или have (got).',$j${"items": [{"before": "Where", "after": "you from? I'm from Rome."}, {"before": "", "after": "you got any brothers or sisters?"}, {"before": "Yes, I", "after": ". I've got two brothers."}, {"before": "No, I", "after": ", but I've got lots of pets!"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('073858a2-4821-53c6-8368-aad09c323cd1',$j${"items": [{"accept": ["are"]}, {"accept": ["Have"]}, {"accept": ["have"]}, {"accept": ["haven't"]}]}$j$::jsonb,'');
