INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e4e0914c-afe3-5fb3-9c16-45652181b97a','a0000000-0000-4000-8000-000000000052','Блок 3. Subject / Object pronouns',3,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('7ce553fb-40f0-57b4-8e3d-8b8714fade15','e4e0914c-afe3-5fb3-9c16-45652181b97a','Subject / Object pronouns',0,'LESSON',70,$j$[{"type": "rule", "text": "Subject pronouns (I, you, he, she, it, we, you, they) come before verbs, instead of nouns or names. Object pronouns (me, you, him, her, it, us, you, them) come after verbs and prepositions."}, {"type": "examples", "items": ["This house is really big! It has got five bedrooms. (It = the house)", "Beth is from Ireland. She is my best friend. (She = Beth)", "We take them for a walk every day.", "Look at me!"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('49cb5094-562e-5b64-a181-c3f193001369','7ce553fb-40f0-57b4-8e3d-8b8714fade15',0,'FILL_BLANK','Заполните пропуски правильными subject/object местоимениями.',$j${"items": [{"before": "This is Jim.", "after": "is my cousin."}, {"before": "Jessica is beautiful today. Look at", "after": "!"}, {"before": "I've got a problem. Can", "after": "help me?"}, {"before": "Look at", "after": "! They can play tennis so well!"}, {"before": "This is my skateboard.", "after": "is red."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('49cb5094-562e-5b64-a181-c3f193001369',$j${"items": [{"accept": ["He"]}, {"accept": ["her"]}, {"accept": ["you"]}, {"accept": ["them"]}, {"accept": ["It"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('70300550-642f-5bc8-9fa0-e1fc81b39f07','7ce553fb-40f0-57b4-8e3d-8b8714fade15',1,'MATCH_PAIRS','Соедините подчёркнутое местоимение с тем, что оно означает (диалог Becky и Sandy).',$j${"left": [{"id": "l1", "label": "you (Have you got a dress?)"}, {"id": "l2", "label": "it (it's really old)"}, {"id": "l3", "label": "us (Alice can join us)"}, {"id": "l4", "label": "her (Call her!)"}], "right": [{"id": "r1", "label": "Becky"}, {"id": "r2", "label": "the dress"}, {"id": "r3", "label": "Becky and Sandy"}, {"id": "r4", "label": "Alice"}]}$j$::jsonb,10);
