INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('1cc66ea6-d7ee-5606-a0b0-9f26bffa6c5e','a0000000-0000-4000-8000-000000000052','Блок 4. Plurals',4,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('98738ac8-5c54-5381-aa67-95314b838424','1cc66ea6-d7ee-5606-a0b0-9f26bffa6c5e','Plurals',0,'LESSON',70,$j$[{"type": "rule", "text": "Most nouns take -s. Nouns ending in -s, -ss, -sh, -ch, -x, -o take -es (glass → glasses, box → boxes, tomato → tomatoes). BUT some -o nouns take only -s (photo → photos, radio → radios)."}, {"type": "rule", "text": "Nouns ending in -f/-fe usually drop it and take -ves (thief → thieves, wife → wives), but some take only -s (roof → roofs, cliff → cliffs). Consonant + y → -ies (butterfly → butterflies); vowel + y → -s (boy → boys)."}, {"type": "examples", "items": ["mouse → mice", "foot → feet", "child → children", "sheep → sheep", "man → men", "person → people"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('68f61d56-b8a8-5695-a647-26afc5139f6f','98738ac8-5c54-5381-aa67-95314b838424',0,'FILL_BLANK','Напишите форму множественного числа.',$j${"items": [{"before": "wife →", "after": ""}, {"before": "baby →", "after": ""}, {"before": "mouse →", "after": ""}, {"before": "tooth →", "after": ""}, {"before": "goose →", "after": ""}, {"before": "watch →", "after": ""}, {"before": "child →", "after": ""}, {"before": "person →", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('68f61d56-b8a8-5695-a647-26afc5139f6f',$j${"items": [{"accept": ["wives"]}, {"accept": ["babies"]}, {"accept": ["mice"]}, {"accept": ["teeth"]}, {"accept": ["geese"]}, {"accept": ["watches"]}, {"accept": ["children"]}, {"accept": ["people"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('93879bc7-921d-59e7-b02f-87f27e148f06','98738ac8-5c54-5381-aa67-95314b838424',1,'CHOOSE','Выберите правильную форму множественного числа.',$j${"items": [{"before": "Jack's got two", "after": "and a cat.", "options": [{"id": "o1", "label": "goldfishs"}, {"id": "o2", "label": "goldfish"}, {"id": "o3", "label": "goldfishes"}]}, {"before": "", "after": "have got really long necks.", "options": [{"id": "o1", "label": "Giraffes"}, {"id": "o2", "label": "Giraves"}, {"id": "o3", "label": "Giraffe"}]}, {"before": "My grandfather has got lots of", "after": "on his farm.", "options": [{"id": "o1", "label": "gooses"}, {"id": "o2", "label": "goose"}, {"id": "o3", "label": "geese"}]}, {"before": "The", "after": "in the photo are very cute!", "options": [{"id": "o1", "label": "babys"}, {"id": "o2", "label": "babies"}, {"id": "o3", "label": "baby"}]}, {"before": "Give me five", "after": "and four bananas, please.", "options": [{"id": "o1", "label": "tomatos"}, {"id": "o2", "label": "tomato"}, {"id": "o3", "label": "tomatoes"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('93879bc7-921d-59e7-b02f-87f27e148f06',$j${"items": [{"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o2"}, {"correctId": "o3"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b9909b90-e272-59f4-a94b-5141445b6dc0','98738ac8-5c54-5381-aa67-95314b838424',2,'FILL_BLANK','Перепишите предложение во множественном числе.',$j${"items": [{"before": "It is a fox. →", "after": ""}, {"before": "It is a deer. →", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('b9909b90-e272-59f4-a94b-5141445b6dc0',$j${"items": [{"accept": ["They are foxes.", "They are foxes"]}, {"accept": ["They are deer.", "They are deer"]}]}$j$::jsonb,'');
