INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('3ba6c0bd-8a23-5a3c-9230-306c3bd387f6','a0000000-0000-4000-8000-000000000052','Блок 5. There is / There are - Some / Any',5,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4be2791b-1297-5dfd-b442-c5216726cea1','3ba6c0bd-8a23-5a3c-9230-306c3bd387f6','There is / There are - Some / Any',0,'LESSON',70,$j$[{"type": "rule", "text": "We use there is (there's) for singular and there are for plural to say that something exists. There are has no short form. We use there + be to mention something for the first time; we use it + be to give more details about it."}, {"type": "rule", "text": "Some is used in affirmative sentences (plural countable and uncountable nouns). Any is used in negatives and questions. No can replace not any: There is no milk = There isn't any milk."}, {"type": "examples", "items": ["There is a piano in the living room.", "There aren't any armchairs, but there are two sofas.", "Are there any biscuits in the jar?", "There is some cake on the table. It is for you."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3a127c68-5d3c-5ad0-bdf5-85e5391b8ab9','4be2791b-1297-5dfd-b442-c5216726cea1',0,'CHOOSE','Подчеркните правильное слово: some или any.',$j${"items": [{"before": "There is", "after": "juice in the fridge.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "There aren't", "after": "clothes in the wardrobe.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Are there", "after": "chairs in the living room?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "There are", "after": "cherries in the bowl.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "There is", "after": "garlic in the salad.", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3a127c68-5d3c-5ad0-bdf5-85e5391b8ab9',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('cba8bc4f-7791-59a6-8474-e2b97583e237','4be2791b-1297-5dfd-b442-c5216726cea1',1,'FILL_BLANK','Заполните пропуски: there или it.',$j${"items": [{"before": "", "after": "is someone here to see you. I think it is your friend Darren."}, {"before": "There is someone here to see you. I think", "after": "is your friend Darren."}, {"before": "Is", "after": "a park near here? Yes, there is."}, {"before": "Look!", "after": "is a rainbow in the sky."}, {"before": "There is a rainbow in the sky.", "after": "is really beautiful."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('cba8bc4f-7791-59a6-8474-e2b97583e237',$j${"items": [{"accept": ["There"]}, {"accept": ["it"]}, {"accept": ["there"]}, {"accept": ["There"]}, {"accept": ["It"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c00bec50-5c6e-57d1-b1ba-7f90cbe8e62b','4be2791b-1297-5dfd-b442-c5216726cea1',2,'FILL_BLANK','Заполните пропуски правильной формой there is / there are.',$j${"items": [{"before": "In the garden,", "after": "a swimming pool."}, {"before": "On the ground floor,", "after": "a kitchen, a dining room, a study and a living room."}, {"before": "In the living room,", "after": "a lovely old fireplace."}, {"before": "", "after": "any bedrooms downstairs."}, {"before": "On the first floor,", "after": "three bedrooms and two bathrooms."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c00bec50-5c6e-57d1-b1ba-7f90cbe8e62b',$j${"items": [{"accept": ["there is", "there's"]}, {"accept": ["there are", "there is"]}, {"accept": ["there is", "there's"]}, {"accept": ["There aren't", "There are not"]}, {"accept": ["there are"]}]}$j$::jsonb,'');
INSERT INTO "LessonUnit" (id,"moduleId",title,subtitle,"orderIndex",kind,"passThreshold",intro) VALUES ('e6968c4a-6b39-592c-a26d-f7c6bac2b0e7','3ba6c0bd-8a23-5a3c-9230-306c3bd387f6','Тест блока: There is / There are - Some / Any','Ответь верно минимум на 70%, чтобы открыть следующий блок',1,'TEST',70,'[]'::jsonb);
