INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('f0a6ea87-6b4d-5883-b316-83b9cefae168','a0000000-0000-4000-8000-000000000052','Блок 6. This / These - That / Those',6,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('ad8d3882-73a4-5a5b-a157-efa300cb7810','f0a6ea87-6b4d-5883-b316-83b9cefae168','This / These - That / Those',0,'LESSON',70,$j$[{"type": "rule", "text": "We use this (singular) / these (plural) for people, animals or things near us, to introduce people, and to introduce oneself on the phone. We use that (singular) / those (plural) for things far away from us."}, {"type": "rule", "text": "In wh-questions we answer with it or they: What's this/that? It's an insect. What are these/those? They are insects."}, {"type": "examples", "items": ["This is a book. / These are books.", "That is a helicopter! / Those are helicopters!", "Mark, this is Julie Grant.", "Hello? This is Amy Peterson speaking."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3458d786-4ea2-5e4f-8940-c6bb5890b22d','ad8d3882-73a4-5a5b-a157-efa300cb7810',0,'FILL_BLANK','Перепишите предложение во множественном числе.',$j${"items": [{"before": "That is a laptop. →", "after": ""}, {"before": "This is a skirt. →", "after": ""}, {"before": "That is a foot. →", "after": ""}, {"before": "This is a TV. →", "after": ""}, {"before": "That is a cupboard. →", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('3458d786-4ea2-5e4f-8940-c6bb5890b22d',$j${"items": [{"accept": ["Those are laptops.", "Those are laptops"]}, {"accept": ["These are skirts.", "These are skirts"]}, {"accept": ["Those are feet.", "Those are feet"]}, {"accept": ["These are TVs.", "These are TVs"]}, {"accept": ["Those are cupboards.", "Those are cupboards"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('fe23df40-9652-5617-88d4-c1f251eab0c1','ad8d3882-73a4-5a5b-a157-efa300cb7810',1,'CHOOSE','Выберите this, that, these или those.',$j${"items": [{"before": "Mum,", "after": "is my new friend Monica.", "options": [{"id": "o1", "label": "this"}, {"id": "o2", "label": "those"}]}, {"before": "My feet are killing me.", "after": "shoes are too small.", "options": [{"id": "o1", "label": "these"}, {"id": "o2", "label": "that"}]}, {"before": "Mmm!", "after": "cake is delicious!", "options": [{"id": "o1", "label": "this"}, {"id": "o2", "label": "these"}]}, {"before": "Who's", "after": "boy over there?", "options": [{"id": "o1", "label": "these"}, {"id": "o2", "label": "that"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('fe23df40-9652-5617-88d4-c1f251eab0c1',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
