INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('2324267f-7e4d-5205-b03e-96e3f8a5fd81','a0000000-0000-4000-8000-000000000052','Блок 7. Possessive adjectives - Possessive pronouns',7,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('da8a82b4-1be9-5c3f-afe7-1dd3642144af','2324267f-7e4d-5205-b03e-96e3f8a5fd81','Possessive adjectives - Possessive pronouns',0,'LESSON',70,$j$[{"type": "rule", "text": "Possessive adjectives (my, your, his, her, its, our, your, their) come before nouns and show possession/relationship: This is your suitcase. Possessive pronouns (mine, yours, his, hers, ours, yours, theirs) are NOT followed by a noun: That car is ours. There is no possessive pronoun for it."}, {"type": "rule", "text": "Use a friend of mine/yours/his to mean one of a number of friends. Its = possessive adjective (Its tail is long). It's = it is / it has (It's fantastic!)."}, {"type": "examples", "items": ["This is his new car.", "They are our grandparents.", "That car is ours.", "Julie is a friend of mine."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a94b8eb3-dfb3-5e92-bf80-a82cc16cde10','da8a82b4-1be9-5c3f-afe7-1dd3642144af',0,'FILL_BLANK','Заполните пропуски нужным притяжательным прилагательным или местоимением.',$j${"items": [{"before": "Where is Mary? She's out with a friend of", "after": "."}, {"before": "Is this", "after": "laptop? No, it's mine."}, {"before": "Is this his laptop? No, it's", "after": "."}, {"before": "This is our new house. Where is", "after": "bedroom?"}, {"before": "Does your dad know Mr Clark? Yes! He's a friend of", "after": "."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('a94b8eb3-dfb3-5e92-bf80-a82cc16cde10',$j${"items": [{"accept": ["hers"]}, {"accept": ["his"]}, {"accept": ["mine"]}, {"accept": ["your"]}, {"accept": ["his"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('390027eb-a853-5c19-833e-f3604e91c915','da8a82b4-1be9-5c3f-afe7-1dd3642144af',1,'FILL_BLANK','Заполните пропуски: its или it''s.',$j${"items": [{"before": "Look at that dog!", "after": "ears are very long!"}, {"before": "This isn't her book.", "after": "his."}, {"before": "This is a great house!", "after": "huge."}, {"before": "Let's go outside.", "after": "a nice, sunny day."}, {"before": "I've got a Persian cat.", "after": "fur is thick and soft."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('390027eb-a853-5c19-833e-f3604e91c915',$j${"items": [{"accept": ["Its"]}, {"accept": ["It's", "It is"]}, {"accept": ["It's", "It is"]}, {"accept": ["It's", "It is"]}, {"accept": ["Its"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('81ff56b4-9112-5971-a2d8-373848290f4f','da8a82b4-1be9-5c3f-afe7-1dd3642144af',2,'CHOOSE','Подчеркните правильное притяжательное прилагательное или местоимение.',$j${"items": [{"before": "Where are", "after": "parents?", "options": [{"id": "o1", "label": "your"}, {"id": "o2", "label": "yours"}]}, {"before": "They're staying at", "after": "house by the sea.", "options": [{"id": "o1", "label": "our"}, {"id": "o2", "label": "ours"}]}, {"before": "We can listen to", "after": "new CDs.", "options": [{"id": "o1", "label": "my"}, {"id": "o2", "label": "mine"}]}, {"before": "I've got some CDs of", "after": ", too.", "options": [{"id": "o1", "label": "your"}, {"id": "o2", "label": "yours"}]}]}$j$::jsonb,10);
