INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('4b39ea52-8cc0-508c-a33f-6fe80c6ad273','a0000000-0000-4000-8000-000000000052','Блок 8. Possessive Case',8,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('701ebb44-9248-5cdf-be48-aaeb4fa647a2','4b39ea52-8cc0-508c-a33f-6fe80c6ad273','Possessive Case',0,'LESSON',70,$j$[{"type": "rule", "text": "Add 's after names and singular nouns (Jack's car). Add only an apostrophe to plural nouns ending in -s (the students' library). With irregular plurals add 's (the men's cars). When something belongs to two people together, add 's to the last noun (Ted and Natasha's house); when each has their own, add 's to each (Christine's and Jenny's coats)."}, {"type": "rule", "text": "Use of for things or parts of things (the door of the house). Use 's for a place (at Ann's = Ann's house; at the butcher's = the shop) and for time (five minutes' walk, a year's work)."}, {"type": "examples", "items": ["The girl's bag is red.", "The students' library is on the second floor.", "These are the men's cars.", "Our hotel is five minutes' walk from the beach."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e41a120b-d8c8-59ae-92a6-f7bcb8640af3','701ebb44-9248-5cdf-be48-aaeb4fa647a2',0,'CHOOSE','Подчеркните правильную притяжательную форму.',$j${"items": [{"before": "My", "after": "name is Martin.", "options": [{"id": "o1", "label": "brother's"}, {"id": "o2", "label": "brothers'"}]}, {"before": "Our rabbits'", "after": "are Shadow and Flopsy.", "options": [{"id": "o1", "label": "rabbit's"}, {"id": "o2", "label": "rabbits'"}]}, {"before": "Those are the", "after": "sweaters.", "options": [{"id": "o1", "label": "men's"}, {"id": "o2", "label": "mens'"}]}, {"before": "Is this the", "after": "room?", "options": [{"id": "o1", "label": "childrens'"}, {"id": "o2", "label": "children's"}]}, {"before": "We can't visit Sue. She's at", "after": ".", "options": [{"id": "o1", "label": "Marys"}, {"id": "o2", "label": "Mary's"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e41a120b-d8c8-59ae-92a6-f7bcb8640af3',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d03b4ff4-b897-5066-b7c4-874742530119','701ebb44-9248-5cdf-be48-aaeb4fa647a2',1,'FILL_BLANK','Поставьте слова в скобках в правильную притяжательную форму.',$j${"items": [{"before": "They're my", "after": "sons. (sister)"}, {"before": "That man is", "after": "dad. (Steve and Brian)"}, {"before": "What's your", "after": "name? (sister)"}, {"before": "Her", "after": "name is Roy. (husband)"}, {"before": "Those dogs are my", "after": ". (cousins)"}]}$j$::jsonb,10);
