INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8a4e4695-071f-584a-88c7-1cec976acc13','701ebb44-9248-5cdf-be48-aaeb4fa647a2',2,'FILL_BLANK','Перепишите, используя притяжательную форму со временем (как в примере: a ten minutes'' rest).',$j${"items": [{"before": "It's a drive of three hours from my house. → It's", "after": "from my house."}, {"before": "The sales this year are really good. →", "after": "are really good."}, {"before": "It's a walk of five minutes to the school. → It's", "after": "to the school."}, {"before": "The prize for this week is a brand new car. →", "after": "is a brand new car."}]}$j$::jsonb,10);
