INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('2101ce53-2b53-5077-8c97-99932ffe08e2','a0000000-0000-4000-8000-000000000052','Блок 9. Prepositions of Time',9,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('76eb62e4-c30d-5e38-be24-788f77ca8fba','2101ce53-2b53-5077-8c97-99932ffe08e2','Prepositions of Time',0,'LESSON',70,$j$[{"type": "rule", "text": "AT: the time (at 2 o'clock), holidays (at Christmas), and expressions (at night, at noon, at the weekend, at the moment). IN: months (in May), seasons (in winter), years (in 2008), parts of day (in the morning), in an hour. ON: days (on Tuesday), dates (on 13th May), specific parts of a day (on Saturday morning)."}, {"type": "rule", "text": "Use from ... to and during for duration (from 6 to 8; during the day). We do NOT use prepositions of time with today, tomorrow, tonight, yesterday, or before this, last, next, every, all, each. in time = early enough; on time = at the right time."}, {"type": "examples", "items": ["We have breakfast at 9 o'clock every day.", "They go ice-skating in winter.", "He has piano lessons on Saturday mornings.", "The bus is always on time."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('09fa6c13-5b78-50d4-aa57-efa62d2d8d1e','76eb62e4-c30d-5e38-be24-788f77ca8fba',0,'FILL_BLANK','Заполните пропуски: at, in, on, from или during.',$j${"items": [{"before": "When is your guitar lesson? It's", "after": "Saturday afternoon."}, {"before": "John's late. Don't worry. He'll be here", "after": "a minute."}, {"before": "What month is your sister's birthday? It's", "after": "June."}, {"before": "I work", "after": "the evenings, but I don't work during the day."}, {"before": "Where's John? It's 9 o'clock. Don't worry! He's always", "after": "time."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('09fa6c13-5b78-50d4-aa57-efa62d2d8d1e',$j${"items": [{"accept": ["on"]}, {"accept": ["in"]}, {"accept": ["in"]}, {"accept": ["in"]}, {"accept": ["on"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e8be8211-c90b-54af-8a2e-2d41d7e2bf7c','76eb62e4-c30d-5e38-be24-788f77ca8fba',1,'CHOOSE','Выберите правильный предлог времени.',$j${"items": [{"before": "My birthday is", "after": "May.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "in"}, {"id": "o3", "label": "at"}]}, {"before": "I have to leave", "after": "a minute.", "options": [{"id": "o1", "label": "at"}, {"id": "o2", "label": "in"}, {"id": "o3", "label": "on"}]}, {"before": "I've got a meeting", "after": "20th June.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "during"}, {"id": "o3", "label": "from"}]}, {"before": "Is John busy", "after": "present?", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "in"}, {"id": "o3", "label": "at"}]}, {"before": "I work at a summer camp", "after": "the holidays.", "options": [{"id": "o1", "label": "during"}, {"id": "o2", "label": "all"}, {"id": "o3", "label": "last"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e8be8211-c90b-54af-8a2e-2d41d7e2bf7c',$j${"items": [{"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o3"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2912b7df-d5ce-5c4e-95af-f12acd6417f4','76eb62e4-c30d-5e38-be24-788f77ca8fba',2,'FILL_BLANK','Заполните пропуски правильным предлогом времени (at/in/on).',$j${"items": [{"before": "What time do you get up", "after": "the morning?"}, {"before": "What time do you eat dinner", "after": "night?"}, {"before": "What do you do", "after": "the weekends?"}, {"before": "Is your birthday", "after": "the spring?"}, {"before": "Do you go to bed", "after": "midnight?"}]}$j$::jsonb,10);
