INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('a0925228-e213-5238-9e43-63729da46de1','a0000000-0000-4000-8000-000000000052','Блок 10. Prepositions of Place',10,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('4921ea66-9cc1-5adc-804f-b41f29dcb887','a0925228-e213-5238-9e43-63729da46de1','Prepositions of Place',0,'LESSON',70,$j$[{"type": "rule", "text": "Prepositions of place say where somebody/something is: on, under, in front of, behind, beside/next to, near, at, in, between, among, opposite. Use between for the middle of two things/people; use among for three or more."}, {"type": "rule", "text": "AT: at school, at work, at home, at the airport, at a party, and with a house number (at 18, Broxton Street). IN: in bed, in hospital, in a photo, in a car, and with cities/countries (in Rome). ON: on the left/right, on the first floor, on a bus/train, on a chair (BUT in an armchair)."}, {"type": "examples", "items": ["Brad is in front of the tree.", "Brad is between two trees.", "Brad is near the forest.", "My dad loves sitting in the armchair."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6f293295-a204-5501-8b01-4cbd46082b2b','4921ea66-9cc1-5adc-804f-b41f29dcb887',0,'CHOOSE','Подчеркните правильный предлог места.',$j${"items": [{"before": "Maths is my favourite subject", "after": "school.", "options": [{"id": "o1", "label": "at"}, {"id": "o2", "label": "on"}]}, {"before": "My new camera is", "after": "the table.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "on"}]}, {"before": "There is a party", "after": "Jake's house tonight.", "options": [{"id": "o1", "label": "at"}, {"id": "o2", "label": "on"}]}, {"before": "The museum is opposite the art gallery, but Clare is hiding", "after": "the tree.", "options": [{"id": "o1", "label": "in front of"}, {"id": "o2", "label": "behind"}]}, {"before": "My dad loves sitting", "after": "the armchair next to the fireplace.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "in"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6f293295-a204-5501-8b01-4cbd46082b2b',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('adac38ea-1f69-5121-98d6-0603c39a87b8','4921ea66-9cc1-5adc-804f-b41f29dcb887',1,'FILL_BLANK','Заполните пропуски: at, on или in.',$j${"items": [{"before": "Where's your mum? She's", "after": "work."}, {"before": "Excuse me, where's the library? It's", "after": "the seventh floor."}, {"before": "Is Georgia", "after": "the doctor's? Yes, she's got a bad cold."}, {"before": "There is a nice film", "after": "at the cinema."}, {"before": "We are from Italy but we live", "after": "Sweden."}]}$j$::jsonb,10);
