INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('fd4c5bd4-6e09-55cf-a67f-e83f9f6461ca','4921ea66-9cc1-5adc-804f-b41f29dcb887',2,'FILL_BLANK','Заполните пропуски: at или in + слово из списка (bed, the park, home, the airport).',$j${"items": [{"before": "Don't call Jack now. He isn't", "after": "."}, {"before": "The weather's great! We can go for a picnic", "after": "today."}, {"before": "My aunt's sick. She's", "after": "right now."}, {"before": "What time does your flight arrive? I can meet you", "after": "."}]}$j$::jsonb,10);
