INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('a7d33160-ee53-5bda-ab6b-86344f0facff','a0000000-0000-4000-8000-000000000052','Блок 11. Question Words',11,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b9e86197-0560-5981-9485-8bdaeac25486','a7d33160-ee53-5bda-ab6b-86344f0facff','Question Words',0,'LESSON',70,$j$[{"type": "rule", "text": "Question words ask about someone or something: who/whose (people, possession), which/what (things — which for a limited choice, what for an unlimited choice), where (place), when/how long/how often/what time (time), why (reason)."}, {"type": "rule", "text": "how much (quantity/price), how many (number), how (manner), how old (age), how far (distance), how tall/how long (size). Answers to why often begin with because."}, {"type": "examples", "items": ["Whose dog is this? It's Pam's.", "Which singer do you like best - Shakira or Beyonce?", "How many bedrooms are there? Three.", "Why are you happy? Because it's my birthday!"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6ac9d438-429b-518b-91e4-8a647fbb0656','b9e86197-0560-5981-9485-8bdaeac25486',0,'FILL_BLANK','Заполните пропуски: many, much, far, tall, often, long или old.',$j${"items": [{"before": "How", "after": "is it to the train station? It's only ten minutes' walk."}, {"before": "How", "after": "is the blue dress? It costs £35."}, {"before": "How", "after": "are you? I'm 14."}, {"before": "How", "after": "do you go swimming? Three or four times a week."}, {"before": "How", "after": "are you? About 1.7 metres."}, {"before": "How", "after": "brothers have you got? Two."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('6ac9d438-429b-518b-91e4-8a647fbb0656',$j${"items": [{"accept": ["far"]}, {"accept": ["much"]}, {"accept": ["old"]}, {"accept": ["often"]}, {"accept": ["tall"]}, {"accept": ["many"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('693733b2-294c-5ebb-83fe-73f3f9c3b2f4','b9e86197-0560-5981-9485-8bdaeac25486',1,'CHOOSE','Выберите правильное вопросительное слово.',$j${"items": [{"before": "", "after": "gloves are those? They're Susan's.", "options": [{"id": "o1", "label": "Who"}, {"id": "o2", "label": "Whose"}]}, {"before": "", "after": "is your bike? It's in the garden.", "options": [{"id": "o1", "label": "Where"}, {"id": "o2", "label": "What"}]}, {"before": "", "after": "jacket is yours? The green one.", "options": [{"id": "o1", "label": "Which"}, {"id": "o2", "label": "What"}]}, {"before": "", "after": "is Bill so happy? Because it's his birthday.", "options": [{"id": "o1", "label": "Why"}, {"id": "o2", "label": "How"}]}, {"before": "", "after": "is the weather like in Spain? It's really hot!", "options": [{"id": "o1", "label": "When"}, {"id": "o2", "label": "What"}]}]}$j$::jsonb,10);
