INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('77e12aba-65d5-5be2-9209-cd193a318b5a','a0000000-0000-4000-8000-000000000052','Блок 14. Present Simple vs Present Continuous',14,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('052dc94d-0c85-5beb-b9fc-d14513e3837a','77e12aba-65d5-5be2-9209-cd193a318b5a','Present Simple vs Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the present simple for daily routines, habits, permanent states, timetables and general truths. Time expressions: usually, always, every day, in the morning, at night."}, {"type": "rule", "text": "We use the present continuous for actions happening at the time of speaking, temporary actions and fixed future arrangements. Time expressions: now, at the moment, these days, tomorrow. It is also used with 'always' to express annoyance."}, {"type": "rule", "text": "Stative verbs (like, love, hate, want, know, need, believe, understand, remember, forget) have no continuous forms."}, {"type": "examples", "items": ["Sharon goes horse-riding every Sunday.", "He is doing an experiment at the moment.", "I want an ice cream. (NOT: I'm wanting)"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f8184dbb-3e86-5948-b356-216d317332b5','052dc94d-0c85-5beb-b9fc-d14513e3837a',0,'FILL_BLANK','Напишите форму глагола для 3-го лица единственного числа (he/she/it).',$j${"items": [{"before": "shout →", "after": ""}, {"before": "wish →", "after": ""}, {"before": "try →", "after": ""}, {"before": "catch →", "after": ""}, {"before": "go →", "after": ""}, {"before": "kiss →", "after": ""}, {"before": "save →", "after": ""}, {"before": "sing →", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f8184dbb-3e86-5948-b356-216d317332b5',$j${"items": [{"accept": ["shouts"]}, {"accept": ["wishes"]}, {"accept": ["tries"]}, {"accept": ["catches"]}, {"accept": ["goes"]}, {"accept": ["kisses"]}, {"accept": ["saves"]}, {"accept": ["sings"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('fb7e4c92-dcae-5988-bfed-5a850a49c18d','052dc94d-0c85-5beb-b9fc-d14513e3837a',1,'FILL_BLANK','Добавьте -ing и напишите правильную форму.',$j${"items": [{"before": "have →", "after": ""}, {"before": "tie →", "after": ""}, {"before": "chat →", "after": ""}, {"before": "run →", "after": ""}, {"before": "lie →", "after": ""}, {"before": "put →", "after": ""}, {"before": "get →", "after": ""}, {"before": "swim →", "after": ""}, {"before": "ride →", "after": ""}, {"before": "use →", "after": ""}]}$j$::jsonb,10);
