INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a889f6ee-afb7-5a80-8537-e6c90943a8d5','052dc94d-0c85-5beb-b9fc-d14513e3837a',2,'FILL_BLANK','Заполните пропуски словами Do или Does.',$j${"items": [{"before": "", "after": "Charlotte have a dog?"}, {"before": "", "after": "Charlotte's parents have grey hair?"}, {"before": "", "after": "Charlotte's grandad wear glasses?"}, {"before": "", "after": "Charlotte's mum chat on the phone?"}, {"before": "", "after": "Charlotte's dad read newspapers?"}]}$j$::jsonb,10);
