INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4dd9749b-3f1e-5bfc-b345-822c27e12738','052dc94d-0c85-5beb-b9fc-d14513e3837a',3,'FILL_BLANK','Раскройте скобки, употребляя Present Continuous.',$j${"items": [{"before": "Danny and Mandy", "after": "a kite in the park. (fly)"}, {"before": "I", "after": "my bike at the moment. (not/ride)"}, {"before": "", "after": "your bike in the garden? (your dad/fix)"}, {"before": "", "after": "John and Mary tonight? (you/meet)"}]}$j$::jsonb,10);
