INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('dfbf5500-78b5-5331-aa5c-6de93a2d592f','052dc94d-0c85-5beb-b9fc-d14513e3837a',4,'FILL_BLANK','Раскройте скобки, употребляя Present Simple или Present Continuous.',$j${"items": [{"before": "The children", "after": "to school today. (walk)"}, {"before": "Lauren", "after": "to bed early every night. (go)"}, {"before": "She", "after": "in New York City. (live)"}, {"before": "Helen", "after": "on the phone at the moment. (not/talk)"}, {"before": "Sally usually", "after": "TV in the evening. (watch)"}, {"before": "Jim", "after": "the Net at the weekends. (surf)"}, {"before": "The boys", "after": "breakfast every morning. (not/eat)"}, {"before": "I", "after": "my grandmother tomorrow. (visit)"}]}$j$::jsonb,10);
