INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ecbdac0b-38ba-529b-a487-06a4de9f3de5','052dc94d-0c85-5beb-b9fc-d14513e3837a',5,'CHOOSE','Выберите правильное выражение времени.',$j${"items": [{"before": "Angela is sleeping", "after": ".", "options": [{"id": "o1", "label": "now"}, {"id": "o2", "label": "often"}]}, {"before": "Tom gets up late", "after": ".", "options": [{"id": "o1", "label": "at present"}, {"id": "o2", "label": "on Sundays"}]}, {"before": "I'm taking swimming lessons", "after": ".", "options": [{"id": "o1", "label": "these days"}, {"id": "o2", "label": "every summer"}]}, {"before": "Does Karen", "after": "wake up early?", "options": [{"id": "o1", "label": "now"}, {"id": "o2", "label": "usually"}]}, {"before": "George isn't playing volleyball", "after": ".", "options": [{"id": "o1", "label": "now"}, {"id": "o2", "label": "every day"}]}]}$j$::jsonb,10);
