INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('af65ae02-4f9e-53da-bfc8-b5b0f4ab6902','052dc94d-0c85-5beb-b9fc-d14513e3837a',6,'FILL_BLANK','Раскройте скобки, употребляя Present Simple или Present Continuous (письмо из Сицилии).',$j${"items": [{"before": "I", "after": "from the beautiful island of Sicily. (write)"}, {"before": "The weather", "after": "hot and sunny. (be)"}, {"before": "we", "after": "most of the day relaxing on the beach. (spend)"}, {"before": "My family and I", "after": "in a hotel by the sea. (stay)"}, {"before": "Right now, I", "after": "on the balcony. (sit)"}, {"before": "I", "after": "fruit juice. (drink)"}, {"before": "My parents", "after": "at the market. (be)"}, {"before": "On Tuesday, we", "after": "for Sardinia. (leave)"}, {"before": "I just", "after": "it here. (love)"}, {"before": "I", "after": "to leave. (not/want)"}]}$j$::jsonb,10);
