INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('a0e6d0bc-e8d7-5106-ad34-e69a38e1c825','a0000000-0000-4000-8000-000000000052','Блок 15. Adverbs of Frequency',15,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('76b21ec3-bacc-5ac8-bdbc-dc23693a9f49','a0e6d0bc-e8d7-5106-ad34-e69a38e1c825','Adverbs of Frequency',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs of frequency show how often something happens: always (100%), usually (75%), often (50%), sometimes (25%), rarely/seldom (10%), never (0%)."}, {"type": "rule", "text": "They go before the main verb but after the verb 'to be'. Rarely, seldom and never have a negative meaning and are never used with 'not'."}, {"type": "examples", "items": ["We often order pizza on Friday nights.", "She is never late for work.", "They rarely go out on Sunday nights."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('28d700a8-d389-57b7-8a31-f1a863b5b4ed','76b21ec3-bacc-5ac8-bdbc-dc23693a9f49',0,'REORDER','Расставьте слова в правильном порядке.',$j${"tiles": ["sometimes", "goes", "the", "park", "on", "Sundays", "He", "to"]}$j$::jsonb,10);
