INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('6ace3a5d-b563-5ea1-a68f-846975045d6f','a0000000-0000-4000-8000-000000000052','Блок 16. The Infinitive',16,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('738a3a48-816f-508a-8c7e-1b7a00135b5d','6ace3a5d-b563-5ea1-a68f-846975045d6f','The Infinitive',0,'LESSON',70,$j$[{"type": "rule", "text": "The to-infinitive is used after verbs like want, decide, hope, need, promise, seem, offer, expect; after be + adjective; with too and enough; to express purpose; and with would like/love/prefer."}, {"type": "rule", "text": "The bare infinitive (without to) is used after modal verbs (can, may, should) and after the verbs let and make."}, {"type": "examples", "items": ["She seems to be really happy.", "I can play the guitar.", "My mum always makes me tidy my room.", "I'm going to the supermarket to buy some juice."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9a23b8e1-126e-5a40-8e53-2187cf044fd7','738a3a48-816f-508a-8c7e-1b7a00135b5d',0,'FILL_BLANK','Поставьте глагол в правильную форму инфинитива (to-infinitive или без to).',$j${"items": [{"before": "This book is too long", "after": "in a week. (read)"}, {"before": "My brother always makes me", "after": "the dog for a walk. (take)"}, {"before": "I know where", "after": "the cheapest CDs in town. (find)"}, {"before": "Mum is going to the bakery", "after": "some bread. (buy)"}, {"before": "You should", "after": "your teacher about this problem. (tell)"}, {"before": "We want", "after": "to Vienna in the spring. (travel)"}, {"before": "I can", "after": "how happy she is. (understand)"}, {"before": "Ella would like", "after": "a famous singer. (become)"}, {"before": "My brother doesn't let me", "after": "his laptop. (use)"}, {"before": "We don't have enough money", "after": "in an expensive hotel. (stay)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9a23b8e1-126e-5a40-8e53-2187cf044fd7',$j${"items": [{"accept": ["to read"]}, {"accept": ["take"]}, {"accept": ["to find"]}, {"accept": ["to buy"]}, {"accept": ["tell"]}, {"accept": ["to travel"]}, {"accept": ["understand"]}, {"accept": ["to become"]}, {"accept": ["use"]}, {"accept": ["to stay"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4d6572c9-33ea-502a-a7c3-caf97328445d','738a3a48-816f-508a-8c7e-1b7a00135b5d',1,'FILL_BLANK','Заполните пропуски правильной формой глаголов: make, buy, come, do, drive, hear, go, run, speak, take.',$j${"items": [{"before": "I promise", "after": "home before 10 o'clock."}, {"before": "Do you know how", "after": "a chocolate cake?"}, {"before": "It's too cold", "after": "for a walk outside."}, {"before": "She's not old enough", "after": "a car."}, {"before": "Matt and Amy can", "after": "German."}, {"before": "I'd like", "after": "a new pair of jeans."}, {"before": "He hopes", "after": "his first marathon this year."}, {"before": "Jack knows how", "after": "his Maths homework."}, {"before": "I'm happy", "after": "you're doing well at school."}, {"before": "You should", "after": "an umbrella with you today."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('4d6572c9-33ea-502a-a7c3-caf97328445d',$j${"items": [{"accept": ["to come"]}, {"accept": ["to make"]}, {"accept": ["to go"]}, {"accept": ["to drive"]}, {"accept": ["speak"]}, {"accept": ["to buy"]}, {"accept": ["to run"]}, {"accept": ["to do"]}, {"accept": ["to hear"]}, {"accept": ["take"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('82825550-cc83-5503-8086-f960f6e99810','738a3a48-816f-508a-8c7e-1b7a00135b5d',2,'CHOOSE','Выберите правильную форму инфинитива.',$j${"items": [{"before": "You should", "after": "your teacher about this.", "options": [{"id": "o1", "label": "tell"}, {"id": "o2", "label": "to tell"}]}, {"before": "We want", "after": "to Vienna in the spring.", "options": [{"id": "o1", "label": "travel"}, {"id": "o2", "label": "to travel"}]}, {"before": "My mum makes me", "after": "my room.", "options": [{"id": "o1", "label": "tidy"}, {"id": "o2", "label": "to tidy"}]}, {"before": "I'd love", "after": "to the cinema tonight.", "options": [{"id": "o1", "label": "go"}, {"id": "o2", "label": "to go"}]}, {"before": "She's too sad", "after": "to the party.", "options": [{"id": "o1", "label": "go"}, {"id": "o2", "label": "to go"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('82825550-cc83-5503-8086-f960f6e99810',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7b48f527-806b-5e55-b04a-387bdef0a0d1','738a3a48-816f-508a-8c7e-1b7a00135b5d',3,'FILL_BLANK','Поставьте глагол в правильную форму инфинитива (диалог).',$j${"items": [{"before": "A: Do you want", "after": "lunch now? (eat)"}, {"before": "B: I'd like", "after": "to the gym first. (go)"}, {"before": "A: Do you know how", "after": "this computer? (use)"}, {"before": "B: Here, let me", "after": "you how. (show)"}, {"before": "A: Can you", "after": "talking, please? (stop)"}, {"before": "B: I promise", "after": "quiet. (be)"}, {"before": "A: Do you expect", "after": "a job this summer? (find)"}, {"before": "B: Yes, I hope", "after": "on my uncle's farm. (work)"}, {"before": "A: John promised", "after": "us at the weekend. (visit)"}, {"before": "B: I'm really happy", "after": "that. (hear)"}]}$j$::jsonb,10);
