INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('8f26588b-408b-5a4a-9eb0-04d26b9cd2a6','a0000000-0000-4000-8000-000000000052','Блок 17. The -ing Form',17,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('807f9f71-2370-540f-a531-26e45c712579','8f26588b-408b-5a4a-9eb0-04d26b9cd2a6','The -ing Form',0,'LESSON',70,$j$[{"type": "rule", "text": "The -ing form is used as a noun; after verbs like like, love, dislike, hate, enjoy, prefer; after 'go' for activities; after start, begin, finish, stop, continue; after prepositions; and after verbs like avoid, admit, deny, mind, suggest, spend."}, {"type": "rule", "text": "Use the to-infinitive (not the -ing form) after would love, would like, would prefer. After see, hear, feel and watch you can use the bare infinitive or the -ing form."}, {"type": "examples", "items": ["Swimming is good for your body.", "Stacy hates getting up early.", "We sometimes go ice-skating in winter.", "I suggest going for a walk."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('753e4d7c-991a-55b6-8df8-67c4502d3cd2','807f9f71-2370-540f-a531-26e45c712579',0,'MATCH_PAIRS','Соедините части предложений, чтобы получились правильные высказывания.',$j${"left": [{"id": "l1", "label": "Steve enjoys"}, {"id": "l2", "label": "I decided"}, {"id": "l3", "label": "It's no use"}, {"id": "l4", "label": "The Simpsons are looking forward to"}, {"id": "l5", "label": "Swimming"}, {"id": "l6", "label": "The magician can"}, {"id": "l7", "label": "Bill and Vicky hope"}, {"id": "l8", "label": "Kelly avoids"}, {"id": "l9", "label": "Can you"}, {"id": "l10", "label": "Would you like"}], "right": [{"id": "r1", "label": "playing computer games. It's his favourite pastime."}, {"id": "r2", "label": "to buy a new laptop."}, {"id": "r3", "label": "trying to fix the TV. We need a new one."}, {"id": "r4", "label": "going on their family holiday."}, {"id": "r5", "label": "is my favourite sport."}, {"id": "r6", "label": "make rabbits disappear."}, {"id": "r7", "label": "to become doctors one day."}, {"id": "r8", "label": "eating fast food because she believes it's unhealthy."}, {"id": "r9", "label": "help me with my Maths homework?"}, {"id": "r10", "label": "to meet my parents?"}]}$j$::jsonb,10);
