INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('00bc40a5-403c-5467-96e7-4fb397d61bab','a0000000-0000-4000-8000-000000000052','Блок 18. Past Simple (Regular & Irregular Verbs)',18,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('84f2a580-dfe9-5e48-82e6-4f55d52a90e0','00bc40a5-403c-5467-96e7-4fb397d61bab','Past Simple (Regular & Irregular Verbs)',0,'LESSON',70,$j$[{"type": "rule", "text": "The past simple is used for actions that happened at a specific time in the past, past habits, actions that happened one after another, and people who are no longer alive."}, {"type": "rule", "text": "Regular verbs add -ed (with spelling changes). Irregular verbs have special forms (come-came, see-saw, break-broke). The negative uses didn't + base form; questions use Did + base form."}, {"type": "examples", "items": ["They went camping last summer.", "First she read the book and then she showed it to her friends.", "They didn't finish. / Did they run?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('b05bd9af-178c-511b-9a77-c79127baa7f0','84f2a580-dfe9-5e48-82e6-4f55d52a90e0',0,'FILL_BLANK','Напишите форму Past Simple.',$j${"items": [{"before": "watch →", "after": ""}, {"before": "open →", "after": ""}, {"before": "arrive →", "after": ""}, {"before": "dance →", "after": ""}, {"before": "visit →", "after": ""}, {"before": "climb →", "after": ""}, {"before": "finish →", "after": ""}, {"before": "cook →", "after": ""}, {"before": "need →", "after": ""}, {"before": "drop →", "after": ""}, {"before": "play →", "after": ""}, {"before": "race →", "after": ""}]}$j$::jsonb,10);
