INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('50cbe8c0-c7f9-56c2-ac17-61dd8c8d7045','84f2a580-dfe9-5e48-82e6-4f55d52a90e0',1,'FILL_BLANK','Раскройте скобки, употребляя Past Simple (текст об Амелии Эрхарт).',$j${"items": [{"before": "Amelia Earhart", "after": "born in Kansas, USA in 1897. (be)"}, {"before": "she", "after": "flying lessons. (take)"}, {"before": "in 1921 she", "after": "her own plane. (buy)"}, {"before": "Her big moment", "after": "in 1932. (come)"}, {"before": "But Amelia", "after": "there. (not/stop)"}, {"before": "Next, she", "after": "to fly around the world! (decide)"}, {"before": "She", "after": "off in March 1937. (set)"}, {"before": "but never", "after": "her destination. (reach)"}, {"before": "Her plane mysteriously", "after": "over the Pacific Ocean. (disappear)"}, {"before": "Rescue teams", "after": "weeks searching. (spend)"}, {"before": "but", "after": "nothing. (find)"}, {"before": "What", "after": "to Amelia on her last flight? (happen)"}]}$j$::jsonb,10);
