INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7483dbb4-2bfe-5e48-b1f8-b95b776663bd','84f2a580-dfe9-5e48-82e6-4f55d52a90e0',2,'FILL_BLANK','Раскройте скобки, употребляя Past Simple (диалог).',$j${"items": [{"before": "A: What", "after": "for dinner? (you/cook)"}, {"before": "B: I", "after": "a pizza. (make)"}, {"before": "A:", "after": "any films last weekend? (you/see)"}, {"before": "B: No, but I", "after": "a nice book. (read)"}, {"before": "A:", "after": "to the gym last night? (they/go)"}, {"before": "B: No, they", "after": "at home. (stay)"}, {"before": "and", "after": "the Net. (surf)"}, {"before": "A:", "after": "his cousin yesterday? (Matt/meet)"}, {"before": "B: Yes, they", "after": "to the football match. (go)"}, {"before": "A: How", "after": "the party? (be)"}, {"before": "B: Everyone", "after": "to the music. (dance)"}, {"before": "and", "after": "along. (sing)"}]}$j$::jsonb,10);
