INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('8dcc8b01-8c0d-5d3b-af3e-586cfad9b9fb','a0000000-0000-4000-8000-000000000052','Блок 19. Used to',19,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('38f8e5b1-919f-50fb-936a-d314020e611a','8dcc8b01-8c0d-5d3b-af3e-586cfad9b9fb','Used to',0,'LESSON',70,$j$[{"type": "rule", "text": "'used to' is a past form used for past habits or things that happened regularly in the past but no longer happen, and for things that were true but are not true any more. It has the same form in all persons."}, {"type": "rule", "text": "Negative: didn't use to. Question: Did ... use to ...? The past simple can replace 'used to' for past habits, but not for single completed past actions."}, {"type": "examples", "items": ["He used to play tennis. / He didn't use to play tennis. / Did he use to play tennis?", "Maggie used to have brown hair when she was young."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5d8bdc8d-dacf-537b-bb0a-5b3dcfa9c19b','38f8e5b1-919f-50fb-936a-d314020e611a',0,'FILL_BLANK','Заполните пропуски правильной формой ''used to'' и глаголов в скобках.',$j${"items": [{"before": "Grandad!", "after": "computer games when you were young? (you/play)"}, {"before": "B: No, I didn't. We", "after": "computer games back then. (not/have)"}, {"before": "A: So, what", "after": "in your free time? (you/do)"}, {"before": "B: I", "after": "my friends after school. (meet)"}, {"before": "and we", "after": "games in the street. (play)"}, {"before": "A:", "after": "films when you were young? (you/watch)"}, {"before": "B: Yes, I did. I", "after": "to the cinema. (go)"}, {"before": "but I", "after": "as many films as I do now. (not/see)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5d8bdc8d-dacf-537b-bb0a-5b3dcfa9c19b',$j${"items": [{"accept": ["Did you use to play"]}, {"accept": ["didn't use to have", "did not use to have"]}, {"accept": ["did you use to do"]}, {"accept": ["used to meet"]}, {"accept": ["used to play"]}, {"accept": ["Did you use to watch"]}, {"accept": ["used to go"]}, {"accept": ["didn't use to see", "did not use to see"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8510131d-09f6-5453-bb2d-f54766920dcd','38f8e5b1-919f-50fb-936a-d314020e611a',1,'SORT_COLUMNS','Распределите предложения: где можно заменить Past Simple на ''used to + глагол'', а где нельзя.',$j${"columns": [{"id": "c1", "label": "Можно заменить на 'used to'"}, {"id": "c2", "label": "Нельзя заменить"}], "items": [{"id": "i1", "label": "Martin watched a lot of cartoons when he was younger."}, {"id": "i2", "label": "Sandra met her friends last night."}, {"id": "i3", "label": "William Wallace lived in Scotland in the 13th century."}, {"id": "i4", "label": "Nita read that book last year."}, {"id": "i5", "label": "The Smiths drove a small car ten years ago."}, {"id": "i6", "label": "Lucy went to bed early last Saturday."}]}$j$::jsonb,10);
