INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('bc84adf4-4cbc-5e55-aa3c-ed82120e22bb','a0000000-0000-4000-8000-000000000052','Блок 20. Prepositions of Movement',20,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f3052e59-dedc-5193-8c48-caffafcba8d6','bc84adf4-4cbc-5e55-aa3c-ed82120e22bb','Prepositions of Movement',0,'LESSON',70,$j$[{"type": "rule", "text": "Prepositions of movement show the direction in which someone or something is moving: along, across, up, down, into, out of, over, from...to, around/round, onto, through, past, towards, off."}, {"type": "rule", "text": "Use 'by' with means of transport (by car, by bus) but 'on foot'. When there is an article, possessive or possessive case before the transport, don't use 'by' (in my car, on the bus)."}, {"type": "examples", "items": ["Brad is diving into the pool.", "Brad is jumping over the tree.", "Brad is running past the tree.", "I go to work by bus. / I go to work on foot."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('02e4a404-b512-56fe-89f0-0e24d34af73b','f3052e59-dedc-5193-8c48-caffafcba8d6',0,'FILL_BLANK','Заполните пропуски предлогами: along, across, past, over, through, round, out of.',$j${"items": [{"before": "When you come", "after": "the train station, turn right."}, {"before": "Walk", "after": "King Street until you see River Road."}, {"before": "Turn left on River Road and go", "after": "the bridge."}, {"before": "Keep walking and go", "after": "the cinema."}, {"before": "Then walk", "after": "the tunnel."}, {"before": "and go", "after": "the corner."}, {"before": "Walk", "after": "to the other side of Pine Lane."}]}$j$::jsonb,10);
