INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('08e366be-7792-502a-9c4c-7eebf7a49ea1','f3052e59-dedc-5193-8c48-caffafcba8d6',1,'CHOOSE','Выберите правильный предлог.',$j${"items": [{"before": "It flies", "after": "the city to see the traffic.", "options": [{"id": "o1", "label": "over"}, {"id": "o2", "label": "up"}]}, {"before": "Look! The leaves are falling", "after": "the trees!", "options": [{"id": "o1", "label": "off"}, {"id": "o2", "label": "out of"}]}, {"before": "I lost the signal when I passed", "after": "a tunnel.", "options": [{"id": "o1", "label": "through"}, {"id": "o2", "label": "towards"}]}, {"before": "It goes", "after": "Paris to Lyon.", "options": [{"id": "o1", "label": "from"}, {"id": "o2", "label": "off"}]}, {"before": "We can go", "after": "my car.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "in"}]}, {"before": "No, I go", "after": "foot.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "on"}]}, {"before": "I saw you get", "after": "a taxi last night.", "options": [{"id": "o1", "label": "past"}, {"id": "o2", "label": "out of"}]}, {"before": "I can't climb", "after": "the boat! It's too high!", "options": [{"id": "o1", "label": "onto"}, {"id": "o2", "label": "over"}]}]}$j$::jsonb,10);
