INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3671719f-df6d-5510-bc60-e0c86fa0f3cd','f3052e59-dedc-5193-8c48-caffafcba8d6',2,'CHOOSE','Выберите правильный предлог.',$j${"items": [{"before": "Your shoes are", "after": "the table.", "options": [{"id": "o1", "label": "under"}, {"id": "o2", "label": "between"}]}, {"before": "The girl is cycling", "after": "the tunnel.", "options": [{"id": "o1", "label": "across"}, {"id": "o2", "label": "through"}]}, {"before": "Our house is", "after": "the hospital.", "options": [{"id": "o1", "label": "next to"}, {"id": "o2", "label": "in"}]}, {"before": "The train leaves", "after": "ten minutes.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "at"}]}, {"before": "I go to school", "after": "bus every day.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "by"}]}, {"before": "David is my best friend", "after": "school.", "options": [{"id": "o1", "label": "on"}, {"id": "o2", "label": "at"}]}, {"before": "You should be careful when you walk", "after": "the street.", "options": [{"id": "o1", "label": "across"}, {"id": "o2", "label": "past"}]}, {"before": "We can go to the cinema", "after": "Friday night.", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "on"}]}]}$j$::jsonb,10);
