INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('3b9e85a4-7c63-5384-a47b-54b2ccc6f7c1','a0000000-0000-4000-8000-000000000052','Блок 21. Past Continuous',21,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('e2062f84-c565-5cbf-b636-334b1d7a082f','3b9e85a4-7c63-5384-a47b-54b2ccc6f7c1','Past Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "The Past Continuous is formed with was/were + verb -ing. Example: I/He/She/It was sleeping. We/You/They were sleeping."}, {"type": "text", "text": "We use the Past Continuous for an action which was in progress at a stated time in the past, for a past action which was in progress when another (shorter) action interrupted it, and for two or more actions which were happening at the same time. Time expressions: while, as, when, all day/night/morning."}, {"type": "examples", "items": ["Kelly was shopping at 5 o'clock yesterday afternoon.", "They were talking when his mobile rang.", "Linda was drawing while her mum was cooking.", "The sun was shining and the wind was blowing."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c2e5c560-85ad-5d72-a752-74170af15f98','e2062f84-c565-5cbf-b636-334b1d7a082f',0,'FILL_BLANK','Поставьте глаголы в скобках в Past Continuous.',$j${"items": [{"before": "When I came home yesterday, Mum", "after": "lunch. (cook)"}, {"before": "My brothers Pete and Bill", "after": "the Net. (surf)"}, {"before": "Some children", "after": "in the sea. (swim)"}, {"before": "An elderly couple", "after": "on the sand. (sit)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c2e5c560-85ad-5d72-a752-74170af15f98',$j${"items": [{"accept": ["was cooking"]}, {"accept": ["were surfing"]}, {"accept": ["were swimming"]}, {"accept": ["was sitting"]}]}$j$::jsonb,'');
