INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('8347f107-10e9-5f25-833f-664eba84c778','a0000000-0000-4000-8000-000000000052','Блок 22. Past Simple vs Past Continuous',22,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('cb3dd768-092e-5c46-b986-b2205d0f6c30','8347f107-10e9-5f25-833f-664eba84c778','Past Simple vs Past Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the Past Simple for an action which was completed at a stated time in the past, and for actions which happened immediately one after the other."}, {"type": "rule", "text": "We use the Past Continuous for an action which was in progress at a stated time, for two or more simultaneous actions, and for a past action in progress when another (shorter) past simple action interrupted it."}, {"type": "examples", "items": ["They bought souvenirs yesterday afternoon.", "They were having coffee at 5 o'clock yesterday afternoon.", "He was walking down the street when he slipped on a banana skin.", "She was talking while her teacher was writing on the board."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9b24c3f2-cda9-5e25-b598-69e287132b19','cb3dd768-092e-5c46-b986-b2205d0f6c30',0,'CHOOSE','Выберите правильную форму глагола.',$j${"items": [{"before": "Sophie", "after": "a present when the doorbell rang.", "options": [{"id": "o1", "label": "was wrapping"}, {"id": "o2", "label": "wrapped"}]}, {"before": "Steve", "after": "traditional Greek food on holiday in Greece last year.", "options": [{"id": "o1", "label": "was trying"}, {"id": "o2", "label": "tried"}]}, {"before": "Justin", "after": "some boxes when he tripped over a cable.", "options": [{"id": "o1", "label": "carried"}, {"id": "o2", "label": "was carrying"}]}, {"before": "Last year, we", "after": "to Italy.", "options": [{"id": "o1", "label": "travelled"}, {"id": "o2", "label": "were travelling"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9b24c3f2-cda9-5e25-b598-69e287132b19',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ae804304-6a01-5aec-b296-835c558615db','cb3dd768-092e-5c46-b986-b2205d0f6c30',1,'FILL_BLANK','Поставьте глаголы в скобках в Past Simple или Past Continuous.',$j${"items": [{"before": "Dad", "after": "(sleep) when I was doing my homework."}, {"before": "While Mum was washing the dishes, she", "after": "(break) a glass."}, {"before": "As Kathy was going to school, she", "after": "(bump into) her old friend Sam."}, {"before": "When I", "after": "(open) my eyes, a man was standing over me."}]}$j$::jsonb,10);
