INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c6c442d8-1f4c-5802-80e2-34d726492251','cb3dd768-092e-5c46-b986-b2205d0f6c30',2,'FILL_BLANK','Вставьте did, was или were.',$j${"items": [{"before": "", "after": "Ann and Mary go swimming last weekend?"}, {"before": "", "after": "your parents working all day yesterday?"}, {"before": "What", "after": "you doing at 10 o'clock yesterday evening?"}]}$j$::jsonb,10);
