INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e02d986b-904f-51dd-8534-a0a42dd6e8a8','a0000000-0000-4000-8000-000000000052','Блок 23. Modal Verbs',23,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('e184bf11-5f79-523b-8219-708d85b1da75','e02d986b-904f-51dd-8534-a0a42dd6e8a8','Modal Verbs',0,'LESSON',70,$j$[{"type": "rule", "text": "We use can/can't to express ability in the present, to ask for/give/refuse permission and to express possibility. We use could/couldn't to express general ability in the past."}, {"type": "rule", "text": "We use must/mustn't for obligation, strong advice and prohibition. We use have to for obligation and necessity, and don't have to/needn't for lack of necessity."}, {"type": "rule", "text": "We use should/ought to to give advice. We use may/might/could to ask for permission and to express possibility."}, {"type": "examples", "items": ["She can dance very well. I can't speak French.", "I could play tennis when I was four.", "You mustn't be late for school. Becky has to wear a uniform.", "You should brush your teeth every day. She may/might/could be at the gym."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f4aaefa5-bc25-5b5c-ad44-52f70164b96a','e184bf11-5f79-523b-8219-708d85b1da75',0,'FILL_BLANK','Вставьте can, can''t, could или couldn''t.',$j${"items": [{"before": "Craig is only three years old. He", "after": "read or write yet."}, {"before": "Jenny", "after": "ride a bike last year, but now she can."}, {"before": "", "after": "you speak Spanish when you were ten?"}, {"before": "I", "after": "run quite fast when I was young, but now I'm slow."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f4aaefa5-bc25-5b5c-ad44-52f70164b96a',$j${"items": [{"accept": ["can't", "cannot"]}, {"accept": ["couldn't", "could not"]}, {"accept": ["Could"]}, {"accept": ["could"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('008355e7-dc0c-55a0-b609-27eef334f1e3','e184bf11-5f79-523b-8219-708d85b1da75',1,'CHOOSE','Выберите must, mustn''t, have to или don''t have to.',$j${"items": [{"before": "A doctor", "after": "study for many years.", "options": [{"id": "o1", "label": "must"}, {"id": "o2", "label": "mustn't"}]}, {"before": "A doctor", "after": "be late for work.", "options": [{"id": "o1", "label": "must"}, {"id": "o2", "label": "mustn't"}]}, {"before": "You", "after": "eat or drink in the library.", "options": [{"id": "o1", "label": "must"}, {"id": "o2", "label": "mustn't"}]}, {"before": "You", "after": "go to the supermarket. I went yesterday.", "options": [{"id": "o1", "label": "have to"}, {"id": "o2", "label": "don't have to"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('008355e7-dc0c-55a0-b609-27eef334f1e3',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('391db4bb-8cf0-5ec9-91a9-4a8d5705ffa9','e184bf11-5f79-523b-8219-708d85b1da75',2,'CHOOSE','Выберите правильный вариант для каждой ситуации.',$j${"items": [{"before": "You offer to help your mum, but she says it isn't necessary:", "after": "", "options": [{"id": "o1", "label": "You don't have to help me."}, {"id": "o2", "label": "You mustn't help me."}]}, {"before": "You think your bag is in the kitchen, but you're not sure:", "after": "", "options": [{"id": "o1", "label": "It may be in the kitchen."}, {"id": "o2", "label": "It mustn't be in the kitchen."}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('391db4bb-8cf0-5ec9-91a9-4a8d5705ffa9',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9b7351e9-e02b-5bcf-9cdb-9281f488fe8a','e184bf11-5f79-523b-8219-708d85b1da75',3,'FILL_BLANK','Вставьте подходящий модальный глагол (в скобках указана подсказка).',$j${"items": [{"before": "It wasn't necessary for Tina to come early. Tina", "after": "come so early. (have to)"}, {"before": "She is able to speak English fluently. She", "after": "speak English fluently. (can)"}, {"before": "Perhaps mum is at aunt Lisa's. Mum", "after": "be at aunt Lisa's. (may)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9b7351e9-e02b-5bcf-9cdb-9281f488fe8a',$j${"items": [{"accept": ["didn't have to", "did not have to"]}, {"accept": ["can"]}, {"accept": ["may", "might", "could"]}]}$j$::jsonb,'');
