INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('04134417-374a-5018-9b03-cd90f443806c','a0000000-0000-4000-8000-000000000052','Блок 24. Relative Pronouns and Adverbs',24,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('76af63a9-2d0a-5a03-a515-643c03dff9ab','04134417-374a-5018-9b03-cd90f443806c','Relative Pronouns and Adverbs',0,'LESSON',70,$j$[{"type": "rule", "text": "Relative pronouns introduce relative clauses: who/that for people, which/that for objects and animals, whose for possession."}, {"type": "rule", "text": "Relative adverbs: when refers to time, where refers to place, why gives a reason."}, {"type": "examples", "items": ["An architect is a person who/that designs new buildings.", "Steve is reading a book which/that is about World War I.", "This is Chris whose favourite sport is tennis.", "2007 was the year when they got their degree. This is the house where we lived."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('898806b6-6de4-526e-bcc1-5c642474a2f7','76af63a9-2d0a-5a03-a515-643c03dff9ab',0,'CHOOSE','Выберите правильное относительное местоимение или наречие.',$j${"items": [{"before": "This is the dress", "after": "I bought last week.", "options": [{"id": "o1", "label": "that"}, {"id": "o2", "label": "who"}]}, {"before": "This is the man's dog", "after": "saved my life.", "options": [{"id": "o1", "label": "who"}, {"id": "o2", "label": "which"}]}, {"before": "This is the hotel", "after": "we stayed last year.", "options": [{"id": "o1", "label": "when"}, {"id": "o2", "label": "where"}]}, {"before": "I'm sending an email to my sister", "after": "lives in New Zealand.", "options": [{"id": "o1", "label": "whose"}, {"id": "o2", "label": "who"}]}, {"before": "Jack missed the bus, that's", "after": "he's late.", "options": [{"id": "o1", "label": "why"}, {"id": "o2", "label": "when"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('898806b6-6de4-526e-bcc1-5c642474a2f7',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('71aa43bb-dc5e-51a1-a63d-5494d850c3e0','76af63a9-2d0a-5a03-a515-643c03dff9ab',1,'FILL_BLANK','Вставьте who, which, whose, where или when.',$j${"items": [{"before": "The man", "after": "lives next door is my uncle."}, {"before": "2009 was the year", "after": "they travelled to India."}, {"before": "Is that the woman", "after": "car was stolen yesterday?"}, {"before": "That's the restaurant", "after": "we have dinner every Saturday."}]}$j$::jsonb,10);
