INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('0efd1f8e-495e-5db4-a2e1-df65359f76e3','a0000000-0000-4000-8000-000000000052','Блок 25. Relative Clauses (Defining and Non-defining)',25,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('b1320ad0-29bc-5a5a-8ca5-3aac36943f1e','0efd1f8e-495e-5db4-a2e1-df65359f76e3','Relative Clauses (Defining and Non-defining)',0,'LESSON',70,$j$[{"type": "rule", "text": "Relative clauses identify the noun in the main clause. A defining relative clause gives essential information, is not put in commas, and who/which/that can be omitted when it is the object of the clause."}, {"type": "rule", "text": "A non-defining relative clause gives extra information, is put in commas, the relative pronoun cannot be omitted, and that cannot be used instead of who or which."}, {"type": "examples", "items": ["The athlete who won the race is from the USA.", "People who/that drink and drive can cause an accident.", "My friend Jen, who is from Canada, loves Chinese food."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f3aff2cc-8863-5c84-8398-7cae71864912','b1320ad0-29bc-5a5a-8ca5-3aac36943f1e',0,'MATCH_PAIRS','Соедините части, чтобы получились предложения.',$j${"left": [{"id": "l1", "label": "This is the film"}, {"id": "l2", "label": "The doctor"}, {"id": "l3", "label": "The island"}, {"id": "l4", "label": "The red dress"}], "right": [{"id": "r1", "label": "which I saw last night."}, {"id": "r2", "label": "who treated me at the hospital was very friendly."}, {"id": "r3", "label": "where we went on holiday last summer was Crete."}, {"id": "r4", "label": "which you bought is beautiful."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f3aff2cc-8863-5c84-8398-7cae71864912',$j${"pairs": [{"l": "l1", "r": "r1"}, {"l": "l2", "r": "r2"}, {"l": "l3", "r": "r3"}, {"l": "l4", "r": "r4"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('07cedc9e-93b9-5737-aa4e-2084120f7492','b1320ad0-29bc-5a5a-8ca5-3aac36943f1e',1,'FILL_BLANK','Вставьте правильное относительное местоимение (who или which).',$j${"items": [{"before": "The woman", "after": "lives next door is a fashion designer."}, {"before": "My friend Jen,", "after": "is from Canada, loves Chinese food."}, {"before": "The film Braveheart,", "after": "stars Mel Gibson, is about a Scottish hero."}, {"before": "That's the girl", "after": "babysits my nephew."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('07cedc9e-93b9-5737-aa4e-2084120f7492',$j${"items": [{"accept": ["who", "that"]}, {"accept": ["who"]}, {"accept": ["which"]}, {"accept": ["who", "that"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('07921aee-0579-52d9-9509-d3eff3b8090e','b1320ad0-29bc-5a5a-8ca5-3aac36943f1e',2,'TRUE_FALSE','Верно или неверно?',$j${"statement": "In a non-defining relative clause, we cannot omit the relative pronoun."}$j$::jsonb,10);
