INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('2de6bdcd-f1cc-598a-b415-d5c725f5753b','a0000000-0000-4000-8000-000000000052','Блок 26. Adjectives, Comparatives and Superlatives',26,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('944bca12-2fec-5462-a849-99552ca89b27','2de6bdcd-f1cc-598a-b415-d5c725f5753b','Adjectives, Comparatives and Superlatives',0,'LESSON',70,$j$[{"type": "rule", "text": "Adjectives describe nouns and have the same form in the singular and plural. They go before nouns or after verbs like be, look, taste. Opinion adjectives go before fact adjectives, and fact adjectives follow the order: Size, Age, Shape, Colour, Origin, Material."}, {"type": "rule", "text": "We form the comparative of one and two-syllable adjectives with -er and the superlative with -est. With three-syllable or longer adjectives we use more and most. Irregular: good-better-best, bad-worse-worst, far-farther/further."}, {"type": "examples", "items": ["a nice young girl; a big new round brown Italian wooden desk", "Sienna is younger than Rachel. Erica is the youngest of all.", "beautiful - more beautiful - the most beautiful"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('85017726-1e04-5b59-9353-fee19a2edb27','944bca12-2fec-5462-a849-99552ca89b27',0,'REORDER','Расположите прилагательные в правильном порядке.',$j${"tiles": ["grey", "nice", "big"]}$j$::jsonb,10);
