INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('dbad76f4-8889-5e9f-9804-88a9b6cea91c','944bca12-2fec-5462-a849-99552ca89b27',1,'FILL_BLANK','Напишите сравнительную или превосходную степень прилагательного в скобках.',$j${"items": [{"before": "Sienna is", "after": "than Rachel. (young)"}, {"before": "Erica is the", "after": "of all. (young)"}, {"before": "This is the", "after": "restaurant in town. (expensive)"}, {"before": "Today is", "after": "than yesterday. (good)"}]}$j$::jsonb,10);
