INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('7febb0d7-64b8-51b0-9dcd-9ea1748e14db','a0000000-0000-4000-8000-000000000052','Блок 27. Comparatives and Superlatives',27,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('3f8a5a84-1d1a-5bc5-b8ca-55adfbd53501','7febb0d7-64b8-51b0-9dcd-9ea1748e14db','Comparatives and Superlatives',0,'LESSON',70,$j$[{"type": "rule", "text": "We use the comparative to compare two people, animals, things or places. We can use 'than' with the comparative."}, {"type": "examples", "items": ["Ben is older than Adam.", "Italy is warmer than Iceland."]}, {"type": "rule", "text": "We use the superlative to compare one person, animal or thing with more than one in the same group. We use 'the ... of/in' with the superlative. We use 'in' only to talk about places."}, {"type": "examples", "items": ["Jack is the oldest of all.", "The Pacific Ocean is the largest ocean in the world."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('651eb76f-02a1-593d-9c9f-5edcafcae513','3f8a5a84-1d1a-5bc5-b8ca-55adfbd53501',0,'FILL_BLANK','Поставьте прилагательное в скобках в сравнительную форму и добавьте than.',$j${"items": [{"before": "Italy is", "after": "Iceland. (warm)"}, {"before": "Lake Superior is", "after": "Lake Michigan. (big)"}, {"before": "My new jeans are", "after": "my old ones. (nice)"}, {"before": "Trains are", "after": "cars. (fast)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('651eb76f-02a1-593d-9c9f-5edcafcae513',$j${"items": [{"accept": ["warmer than"]}, {"accept": ["bigger than"]}, {"accept": ["nicer than"]}, {"accept": ["faster than"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0e29321a-0c2e-58a5-8496-b3de0a9db450','3f8a5a84-1d1a-5bc5-b8ca-55adfbd53501',1,'FILL_BLANK','Поставьте прилагательное в скобках в превосходную форму, добавив необходимые слова.',$j${"items": [{"before": "The Pacific is", "after": "ocean in the world. (large)"}, {"before": "Mt Everest is", "after": "mountain in the world. (high)"}, {"before": "Kate is", "after": "of all the sisters. (old)"}, {"before": "I think Brad Pitt is", "after": "actor in Hollywood. (famous)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('0e29321a-0c2e-58a5-8496-b3de0a9db450',$j${"items": [{"accept": ["the largest"]}, {"accept": ["the highest"]}, {"accept": ["the oldest"]}, {"accept": ["the most famous"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('767bcdb8-dee6-5e57-91be-20e3c4bfc826','3f8a5a84-1d1a-5bc5-b8ca-55adfbd53501',2,'CHOOSE','Выберите правильное слово: the, than, in или of.',$j${"items": [{"before": "The Burj Dubai is", "after": "tallest building in the world.", "options": [{"id": "o1", "label": "the"}, {"id": "o2", "label": "than"}]}, {"before": "A plane can travel much faster", "after": "a car.", "options": [{"id": "o1", "label": "than"}, {"id": "o2", "label": "in"}]}, {"before": "What is the longest river", "after": "the world?", "options": [{"id": "o1", "label": "in"}, {"id": "o2", "label": "of"}]}, {"before": "Lions are the most dangerous cats", "after": "all.", "options": [{"id": "o1", "label": "of"}, {"id": "o2", "label": "in"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('767bcdb8-dee6-5e57-91be-20e3c4bfc826',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('1f35bd9b-aedf-54ef-93ab-4ea52ec08021','3f8a5a84-1d1a-5bc5-b8ca-55adfbd53501',3,'TRUE_FALSE','Верно или неверно это утверждение о грамматике?',$j${"statement": "We use 'in' with the superlative only to talk about places, e.g. 'the largest ocean in the world'."}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('1f35bd9b-aedf-54ef-93ab-4ea52ec08021',$j${"value": true}$j$::jsonb,'');
