INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('9a727202-b646-5bd1-a909-f8ecf363dce1','a0000000-0000-4000-8000-000000000052','Блок 28. Types of Comparisons (as ... as, less, least, very/really, much)',28,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('e85cfe50-c9e8-502b-bed4-8985d5e71e61','9a727202-b646-5bd1-a909-f8ecf363dce1','Types of Comparisons (as ... as, less, least, very/really, much)',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'as + adjective + as' to show that two people or things are similar. In negative sentences we use 'not as/so + adjective + as'."}, {"type": "examples", "items": ["Lisa's hair is as long as Susan's.", "My bedroom isn't as big as my sister's."]}, {"type": "rule", "text": "We use 'less + adjective + than' for two things (the opposite of 'more ... than') and 'the least + adjective + of/in' for more than two."}, {"type": "examples", "items": ["This film is less exciting than the one we saw last night.", "This is the least interesting book of all!"]}, {"type": "rule", "text": "We use 'very/really' before the positive form of an adjective, and 'much' before the comparative form."}, {"type": "examples", "items": ["You look very nice!", "Yesterday was much colder than today."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c48e0534-27d9-5827-a97c-dd330e9c1685','e85cfe50-c9e8-502b-bed4-8985d5e71e61',0,'CHOOSE','Выберите much или very.',$j${"items": [{"before": "The car costs", "after": "more than we can afford.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "very"}]}, {"before": "This book is", "after": "better than the last one.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "very"}]}, {"before": "I think football is", "after": "more exciting to watch.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "very"}]}, {"before": "These jeans are", "after": "cheap.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "very"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c48e0534-27d9-5827-a97c-dd330e9c1685',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8a421c9c-346c-5aed-b44a-fb8bd2b87376','e85cfe50-c9e8-502b-bed4-8985d5e71e61',1,'CHOOSE','Выберите less или least.',$j${"items": [{"before": "Comedies are", "after": "exciting than adventure films.", "options": [{"id": "o1", "label": "less"}, {"id": "o2", "label": "least"}]}, {"before": "I don't like this music. It's the", "after": "enjoyable CD in my collection.", "options": [{"id": "o1", "label": "less"}, {"id": "o2", "label": "least"}]}, {"before": "These shoes are", "after": "expensive than those ones.", "options": [{"id": "o1", "label": "less"}, {"id": "o2", "label": "least"}]}, {"before": "Because I think it is the", "after": "healthy food you can get.", "options": [{"id": "o1", "label": "less"}, {"id": "o2", "label": "least"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('8a421c9c-346c-5aed-b44a-fb8bd2b87376',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a11b0280-c83e-5725-9eec-adf06f64a048','e85cfe50-c9e8-502b-bed4-8985d5e71e61',2,'TRUE_FALSE','Верно или неверно?',$j${"statement": "We use 'much' before the comparative form of an adjective, e.g. 'much colder'."}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('a11b0280-c83e-5725-9eec-adf06f64a048',$j${"value": true}$j$::jsonb,'');
