INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('e3766f0e-6d5e-594b-aedb-69eda041f9cc','a0000000-0000-4000-8000-000000000052','Блок 29. Too - Enough',29,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('f6c11efe-a948-5dd1-b0a6-19528e62d274','e3766f0e-6d5e-594b-aedb-69eda041f9cc','Too - Enough',0,'LESSON',70,$j$[{"type": "rule", "text": "'Too' comes before adjectives. It has a negative meaning and shows that something is more than wanted or necessary."}, {"type": "examples", "items": ["I can't buy these shoes. They're too expensive.", "These shoes are too expensive to buy."]}, {"type": "rule", "text": "'Enough' comes after adjectives but before nouns. It has a positive meaning and shows that there is as much of something as needed."}, {"type": "examples", "items": ["She is old enough to drive.", "There isn't enough sugar to make the cake."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('48f7afbe-8328-572c-9265-c990c4932ca5','f6c11efe-a948-5dd1-b0a6-19528e62d274',0,'CHOOSE','Выберите too или enough.',$j${"items": [{"before": "I can't go out tonight. I'm", "after": "busy with all my homework.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "Dave and Cindy are rich", "after": "to buy a Ferrari.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "The tickets are", "after": "expensive to buy.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "Is Tom experienced", "after": "to do this job?", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}, {"before": "My sister is", "after": "young to watch horror films.", "options": [{"id": "o1", "label": "too"}, {"id": "o2", "label": "enough"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('48f7afbe-8328-572c-9265-c990c4932ca5',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('08accf53-bae3-5c85-b20b-9248cbf0d3c9','f6c11efe-a948-5dd1-b0a6-19528e62d274',1,'REORDER','Составьте предложение из данных частей.',$j${"tiles": ["Darren is", "old enough", "to drive"]}$j$::jsonb,10);
