INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('63ecddbe-3fbb-5c1f-93e8-482f0e691a66','c5c1e400-b013-5c9d-af66-ddfe9371619d','Both - Neither/Either',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'both', 'neither' and 'either' to refer to two people or things. 'Both' means 'the one and the other' and takes a plural verb."}, {"type": "examples", "items": ["Both girls are from Paris.", "Both Ben and Tom like comedies."]}, {"type": "rule", "text": "'Neither' means 'not the one or the other' and takes a singular or plural verb in the affirmative. 'Either' means 'one or the other' and takes a singular verb."}, {"type": "examples", "items": ["Neither book is interesting.", "Neither Mary nor John lives in London.", "She's either Spanish or Portuguese."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('85281801-d5b8-5271-8e7b-44ef9be83f9b','63ecddbe-3fbb-5c1f-93e8-482f0e691a66',0,'CHOOSE','Выберите either или neither.',$j${"items": [{"before": "I looked at two bicycles, but I didn't buy", "after": "of them.", "options": [{"id": "o1", "label": "either"}, {"id": "o2", "label": "neither"}]}, {"before": "", "after": "my brother nor my sister wanted to watch a film.", "options": [{"id": "o1", "label": "Either"}, {"id": "o2", "label": "Neither"}]}, {"before": "", "after": "my mum nor my dad can speak French.", "options": [{"id": "o1", "label": "Either"}, {"id": "o2", "label": "Neither"}]}, {"before": "I've got two mobile phones, but", "after": "of them works very well.", "options": [{"id": "o1", "label": "either"}, {"id": "o2", "label": "neither"}]}]}$j$::jsonb,10);
