INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('7bb710d2-e59a-51f8-80cf-bf93429f4d4c','63ecddbe-3fbb-5c1f-93e8-482f0e691a66',1,'CHOOSE','Выберите both, either или neither.',$j${"items": [{"before": "Up or Fantastic Mr Fox? I don't mind. We can watch", "after": "film.", "options": [{"id": "o1", "label": "both"}, {"id": "o2", "label": "either"}, {"id": "o3", "label": "neither"}]}, {"before": "I've got two sisters. They are", "after": "younger than me.", "options": [{"id": "o1", "label": "both"}, {"id": "o2", "label": "either"}, {"id": "o3", "label": "neither"}]}, {"before": "I stayed home.", "after": "John nor Paul could come.", "options": [{"id": "o1", "label": "Both"}, {"id": "o2", "label": "Either"}, {"id": "o3", "label": "Neither"}]}, {"before": "I bought two books. They were", "after": "on sale.", "options": [{"id": "o1", "label": "both"}, {"id": "o2", "label": "either"}, {"id": "o3", "label": "neither"}]}]}$j$::jsonb,10);
