INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('469a2d40-3c38-5bee-89c6-a404ce9f1eb8','a0000000-0000-4000-8000-000000000052','Блок 31. Will - Be going to - Present Continuous',31,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('8bbeda08-281e-5369-8bec-460fe8b4f3ba','469a2d40-3c38-5bee-89c6-a404ce9f1eb8','Will - Be going to - Present Continuous',0,'LESSON',70,$j$[{"type": "rule", "text": "'Will' is used for on-the-spot decisions and for future predictions based on what we believe or imagine."}, {"type": "examples", "items": ["I'll have a salad.", "I think your friend will love this present."]}, {"type": "rule", "text": "'Be going to' is used for future plans and intentions and for predictions based on evidence we can see."}, {"type": "examples", "items": ["He's going to cut the boy's hair.", "Look at that boy! He's going to fall!"]}, {"type": "rule", "text": "The Present Continuous is used for fixed arrangements in the near future. The future simple is NOT used after while, before, until, as soon as, after, if and when - we use the present simple instead."}, {"type": "examples", "items": ["Lyn is travelling from Paris to Brussels in half an hour.", "I'll call you as soon as I arrive."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8dce1073-47d8-5cfd-af8b-369b5c6f88a2','8bbeda08-281e-5369-8bec-460fe8b4f3ba',0,'CHOOSE','Выберите правильную форму: will или be going to.',$j${"items": [{"before": "Look at that boy riding his bike! Oh no! He", "after": "!", "options": [{"id": "o1", "label": "will fall"}, {"id": "o2", "label": "is going to fall"}]}, {"before": "It's really hot in here. Yes, I", "after": "a window.", "options": [{"id": "o1", "label": "will open"}, {"id": "o2", "label": "am going to open"}]}, {"before": "I can't hear a thing! I", "after": "the volume.", "options": [{"id": "o1", "label": "will turn up"}, {"id": "o2", "label": "am going to turn up"}]}, {"before": "It's cloudy. It", "after": "soon.", "options": [{"id": "o1", "label": "will rain"}, {"id": "o2", "label": "is going to rain"}]}]}$j$::jsonb,10);
