INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ae4814b6-03e8-50db-a2a6-950a2f970c45','8bbeda08-281e-5369-8bec-460fe8b4f3ba',1,'CHOOSE','Выберите правильную форму глагола после слов времени.',$j${"items": [{"before": "I'll call you as soon as I", "after": "for work tomorrow.", "options": [{"id": "o1", "label": "leave"}, {"id": "o2", "label": "will leave"}]}, {"before": "Jack will fix the tap as soon as he", "after": "back from the supermarket.", "options": [{"id": "o1", "label": "comes"}, {"id": "o2", "label": "will come"}]}]}$j$::jsonb,10);
