INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('b0e78eba-975a-54e1-8d17-f5b1f5b4ec50','a0000000-0000-4000-8000-000000000052','Блок 32. Conditionals (Types 0, 1 & 2)',32,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('6555c2ca-7362-5e12-99ca-eea63521b227','b0e78eba-975a-54e1-8d17-f5b1f5b4ec50','Conditionals (Types 0, 1 & 2)',0,'LESSON',70,$j$[{"type": "rule", "text": "Type 0 (if + present simple, present simple) expresses something which is always true or a law of nature."}, {"type": "examples", "items": ["If you heat ice, it melts.", "If you don't drink water, you get thirsty."]}, {"type": "rule", "text": "Type 1 (if + present simple, future simple/imperative/modal) expresses something likely to happen in the present or future. We can use 'unless' instead of 'if ... not'."}, {"type": "examples", "items": ["If I don't finish my homework, I won't go to the party.", "Unless you hurry, we'll miss our flight."]}, {"type": "rule", "text": "Type 2 (if + past simple, would/could/might + bare infinitive) expresses an imaginary situation in the present. We use 'If I were you ...' to give advice."}, {"type": "examples", "items": ["If I had a good voice, I would become a singer.", "If I were you, I would exercise more."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('2923771d-3df2-5411-b9f8-0ff9dd45c1d5','6555c2ca-7362-5e12-99ca-eea63521b227',0,'FILL_BLANK','Поставьте глагол в скобках в правильную форму (Type 0).',$j${"items": [{"before": "If you heat water, it", "after": ". (boil)"}, {"before": "If you freeze water, it turns", "after": "ice. (into)"}, {"before": "If you mix blue and red, you", "after": "purple. (get)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('2923771d-3df2-5411-b9f8-0ff9dd45c1d5',$j${"items": [{"accept": ["boils"]}, {"accept": ["into"]}, {"accept": ["get"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('3789bef0-72af-5df2-8667-445290ead28e','6555c2ca-7362-5e12-99ca-eea63521b227',1,'CHOOSE','Выберите правильную форму глагола.',$j${"items": [{"before": "I won't forgive her unless she", "after": ".", "options": [{"id": "o1", "label": "apologise"}, {"id": "o2", "label": "apologises"}]}, {"before": "If you", "after": "water, it turns to ice.", "options": [{"id": "o1", "label": "freeze"}, {"id": "o2", "label": "will freeze"}]}, {"before": "If you read newspapers, you", "after": "a lot.", "options": [{"id": "o1", "label": "learn"}, {"id": "o2", "label": "would learn"}]}, {"before": "If they don't leave now, they", "after": "be late.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "would"}]}]}$j$::jsonb,10);
