INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('5d5031ef-c5ca-5f7b-b445-0b1cba5f21ed','a0000000-0000-4000-8000-000000000052','Блок 33. Adverbs',33,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('3f6c3a13-b039-5faa-946a-a31a7415fd91','5d5031ef-c5ca-5f7b-b445-0b1cba5f21ed','Adverbs',0,'LESSON',70,$j$[{"type": "rule", "text": "We usually form an adverb by adding '-ly' to the adjective (quiet - quietly). Adjectives ending in a consonant + y take '-ily' (happy - happily); those ending in '-le' drop '-e' and take '-y' (possible - possibly)."}, {"type": "rule", "text": "Some adverbs are irregular: good - well, fast - fast, hard - hard, early - early, late - late. Note pairs like hard/hardly and late/lately have different meanings."}, {"type": "examples", "items": ["Amanda sings beautifully.", "My grandmother can hardly see without her glasses."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ccc552f4-f892-5fb4-af2f-f8e34ab2a5c5','3f6c3a13-b039-5faa-946a-a31a7415fd91',0,'FILL_BLANK','Образуйте наречие от данного прилагательного.',$j${"items": [{"before": "quick →", "after": ""}, {"before": "happy →", "after": ""}, {"before": "careful →", "after": ""}, {"before": "good →", "after": ""}, {"before": "possible →", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ccc552f4-f892-5fb4-af2f-f8e34ab2a5c5',$j${"items": [{"accept": ["quickly"]}, {"accept": ["happily"]}, {"accept": ["carefully"]}, {"accept": ["well"]}, {"accept": ["possibly"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('05de4ed0-16e2-5d76-be9e-102d0986230e','3f6c3a13-b039-5faa-946a-a31a7415fd91',1,'CHOOSE','Выберите правильную форму: прилагательное или наречие.',$j${"items": [{"before": "It rained", "after": "last night.", "options": [{"id": "o1", "label": "heavy"}, {"id": "o2", "label": "heavily"}]}, {"before": "You should always cross the road", "after": ".", "options": [{"id": "o1", "label": "careful"}, {"id": "o2", "label": "carefully"}]}, {"before": "Our teacher was very", "after": "with us yesterday.", "options": [{"id": "o1", "label": "angry"}, {"id": "o2", "label": "angrily"}]}, {"before": "Lucy spoke in a", "after": "voice.", "options": [{"id": "o1", "label": "soft"}, {"id": "o2", "label": "softly"}]}]}$j$::jsonb,10);
