INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('d59b6ea0-e63a-56ee-b214-84ba5f476612','3f6c3a13-b039-5faa-946a-a31a7415fd91',3,'SORT_COLUMNS','Распределите наречия по категориям: manner (образа действия) или frequency (частоты).',$j${"columns": [{"id": "c1", "label": "Manner"}, {"id": "c2", "label": "Frequency"}], "items": [{"id": "i1", "label": "quickly"}, {"id": "i2", "label": "never"}, {"id": "i3", "label": "beautifully"}, {"id": "i4", "label": "sometimes"}, {"id": "i5", "label": "carefully"}, {"id": "i6", "label": "often"}]}$j$::jsonb,10);
