INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('3e7030ee-a83c-5cea-bda4-a221f5c8aba7','a0000000-0000-4000-8000-000000000052','Блок 34. Adverbs of Manner and ''Hardly''',34,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('22c13136-8f33-5819-935b-6d5576bc44a5','3e7030ee-a83c-5cea-bda4-a221f5c8aba7','Adverbs of Manner and ''Hardly''',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs describe verbs, adjectives or other adverbs. Many adverbs of manner are formed by adding -ly to an adjective: careful → carefully, serious → seriously."}, {"type": "rule", "text": "'Hardly' means 'almost not'. It is used with the present or past simple: I hardly know him (= I almost don't know him)."}, {"type": "examples", "items": ["He looked at me seriously and told me not to be late.", "The shop assistant was very helpful.", "Jill speaks German well.", "I met Tom only once, so I hardly know him."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e767a3dc-f69a-5598-8210-22034c683625','22c13136-8f33-5819-935b-6d5576bc44a5',0,'FILL_BLANK','Дополните предложения, используя hardly и правильную форму глагола.',$j${"items": [{"before": "John's cut off all his hair. I", "after": "him when I saw him."}, {"before": "Could you speak up, please? I can", "after": "you."}, {"before": "She's really tired today because she", "after": "last night."}, {"before": "Sharon was quiet this evening. She", "after": "a word at dinner."}, {"before": "Your writing is terrible. I can", "after": "it."}, {"before": "I'm really hungry. I", "after": "a thing today."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e767a3dc-f69a-5598-8210-22034c683625',$j${"items": [{"accept": ["hardly recognised", "hardly recognized"]}, {"accept": ["hardly hear"]}, {"accept": ["hardly slept"]}, {"accept": ["hardly said"]}, {"accept": ["hardly read"]}, {"accept": ["hardly ate"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('6d562fd0-0e92-5a41-813d-a2ed196090a8','22c13136-8f33-5819-935b-6d5576bc44a5',1,'CHOOSE','Выберите правильное слово.',$j${"items": [{"before": "We arrived in Lisbon", "after": "last night.", "options": [{"id": "o1", "label": "late"}, {"id": "o2", "label": "lately"}]}, {"before": "We are staying in a", "after": "nice hotel!", "options": [{"id": "o1", "label": "real"}, {"id": "o2", "label": "really"}]}, {"before": "We woke up very early. We", "after": "slept at all.", "options": [{"id": "o1", "label": "hard"}, {"id": "o2", "label": "hardly"}]}, {"before": "We are going to see all the", "after": "sights from the bus.", "options": [{"id": "o1", "label": "wonderful"}, {"id": "o2", "label": "wonderfully"}]}, {"before": "Tour buses are an", "after": "good way to see a city.", "options": [{"id": "o1", "label": "extreme"}, {"id": "o2", "label": "extremely"}]}]}$j$::jsonb,10);
