INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('4544a456-1335-5a17-8db6-18ea19727b68','a0000000-0000-4000-8000-000000000052','Блок 35. Comparative and Superlative Forms of Adverbs',35,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('905cf6e8-2bdc-5a34-868b-eeaf71acdecb','4544a456-1335-5a17-8db6-18ea19727b68','Comparative and Superlative Forms of Adverbs',0,'LESSON',70,$j$[{"type": "rule", "text": "Adverbs form the comparative and superlative like adjectives. Adverbs ending in -ly take more/most: carefully → more carefully → most carefully."}, {"type": "rule", "text": "Adverbs with the same form as the adjective take -er/-est: hard → harder → hardest; early → earlier → earliest. Irregular: well → better → best; badly → worse → worst; far → farther/further → farthest/furthest."}, {"type": "examples", "items": ["A cheetah runs much more quickly than a tiger.", "The cheetah runs the fastest of all animals.", "Jason speaks Italian much more fluently than Patrick."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('768aecac-5a00-52e6-a4c8-e9865f3e9943','905cf6e8-2bdc-5a34-868b-eeaf71acdecb',0,'FILL_BLANK','Напишите указанную форму наречия.',$j${"items": [{"before": "Comparative of 'well':", "after": ""}, {"before": "Superlative of 'fast':", "after": ""}, {"before": "Comparative of 'early':", "after": ""}, {"before": "Superlative of 'badly':", "after": ""}, {"before": "Comparative of 'hard':", "after": ""}, {"before": "Superlative of 'dangerously':", "after": ""}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('768aecac-5a00-52e6-a4c8-e9865f3e9943',$j${"items": [{"accept": ["better"]}, {"accept": ["fastest", "the fastest"]}, {"accept": ["earlier"]}, {"accept": ["worst", "the worst"]}, {"accept": ["harder"]}, {"accept": ["most dangerously", "the most dangerously"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ca8113e6-a346-5ceb-8de4-653442880ef2','905cf6e8-2bdc-5a34-868b-eeaf71acdecb',1,'FILL_BLANK','Раскройте скобки, употребив сравнительную или превосходную форму наречия, добавляя необходимые слова.',$j${"items": [{"before": "He sings", "after": "of all the people in the band. (badly)"}, {"before": "Today I arrived at work", "after": "yesterday. (late)"}, {"before": "Susan dances", "after": "of all. (beautifully)"}, {"before": "You should talk", "after": "to customers than to your friends. (politely)"}, {"before": "Alan works", "after": "of all the employees. (hard)"}, {"before": "My sister writes", "after": "I do. (well)"}, {"before": "My dad drives", "after": "than anyone I know. (carefully)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ca8113e6-a346-5ceb-8de4-653442880ef2',$j${"items": [{"accept": ["the worst", "worst"]}, {"accept": ["later than"]}, {"accept": ["the most beautifully", "most beautifully"]}, {"accept": ["more politely"]}, {"accept": ["the hardest", "hardest"]}, {"accept": ["better than"]}, {"accept": ["more carefully"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('97e959ef-4ea2-5083-9347-abb648303f7d','905cf6e8-2bdc-5a34-868b-eeaf71acdecb',2,'CHOOSE','Выберите very или much.',$j${"items": [{"before": "It was", "after": "more interesting than I expected.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "much"}]}, {"before": "My mum works", "after": "hard.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "much"}]}, {"before": "She works", "after": "harder than anyone I know.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "much"}]}, {"before": "He is a good driver. He drives", "after": "carefully.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "much"}]}, {"before": "The lead singer sang", "after": "better than last year.", "options": [{"id": "o1", "label": "very"}, {"id": "o2", "label": "much"}]}]}$j$::jsonb,10);
