INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('c8edbd9e-ddd7-5856-9192-d85d8e4220d2','a0000000-0000-4000-8000-000000000052','Блок 36. Be Going To - Will - Present Continuous and Conditionals',36,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('beeb2e8e-e680-507c-9bcc-97b8b3499219','c8edbd9e-ddd7-5856-9192-d85d8e4220d2','Be Going To - Will - Present Continuous and Conditionals',0,'LESSON',70,$j$[{"type": "rule", "text": "We use 'be going to' for plans, intentions and predictions based on evidence. We use 'will' for predictions based on belief, promises and on-the-spot decisions. We use the present continuous for fixed arrangements in the near future."}, {"type": "rule", "text": "Type 0 conditional (general truths): If you heat ice, it melts. Type 1 (real/likely): If it rains, we will move inside. Type 2 (imaginary present): If I had a lot of money, I would move there."}, {"type": "examples", "items": ["I am going to have a big garden party.", "I think everyone will have a great time.", "If it rains, we will have to move into the house.", "Unless you study, you won't do well."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('962b488b-4f50-5dcf-a06d-08fde32dda74','beeb2e8e-e680-507c-9bcc-97b8b3499219',0,'CHOOSE','Выберите will или be going to.',$j${"items": [{"before": "Look! She", "after": "hit the ball!", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "is going to"}]}, {"before": "This dress is gorgeous! I", "after": "buy it!", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "am going to"}]}, {"before": "She", "after": "move to Paris next year.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "is going to"}]}, {"before": "I promise I", "after": "write to you.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "am going to"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('962b488b-4f50-5dcf-a06d-08fde32dda74',$j${"items": [{"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('f92d9554-06a5-525a-9f9e-2e954c73ea14','beeb2e8e-e680-507c-9bcc-97b8b3499219',1,'CHOOSE','Выберите правильный вариант (условные предложения).',$j${"items": [{"before": "If you heat ice, it", "after": ".", "options": [{"id": "o1", "label": "melts"}, {"id": "o2", "label": "will melt"}]}, {"before": "Put on a coat or you", "after": "a cold.", "options": [{"id": "o1", "label": "catch"}, {"id": "o2", "label": "will catch"}]}, {"before": "I'd ask for my parents' advice if I", "after": "you.", "options": [{"id": "o1", "label": "am"}, {"id": "o2", "label": "were"}]}, {"before": "We can't play football", "after": "it stops raining.", "options": [{"id": "o1", "label": "unless"}, {"id": "o2", "label": "if not"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('f92d9554-06a5-525a-9f9e-2e954c73ea14',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('992f533e-54e9-5532-a1f8-01388433ec27','a0000000-0000-4000-8000-000000000052','Блок 37. Present Perfect',37,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('88f262f7-05a6-541f-bf84-f169c7510b3d','992f533e-54e9-5532-a1f8-01388433ec27','Present Perfect',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the present perfect with have/has + past participle. We use it for experiences, recently finished actions with visible results, actions at an unspecified past time, and actions that started in the past and still continue."}, {"type": "rule", "text": "'have gone (to)' = someone went somewhere and is still there. 'have been (to)' = someone went there and has come back. Time expressions: already, yet, just, ever, never, for, since, so far, recently, this week."}, {"type": "examples", "items": ["They have lived in this house since 2008.", "I've tried bungee jumping.", "Have you finished your homework yet?", "They haven't arrived yet."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ee12b338-86eb-5be7-ae1f-f796d6017e5b','88f262f7-05a6-541f-bf84-f169c7510b3d',0,'FILL_BLANK','Раскройте скобки, употребив глагол в present perfect.',$j${"items": [{"before": "He", "after": "all his exams. (just/pass)"}, {"before": "I", "after": "it before. (never/smell)"}, {"before": "", "after": "Tina? (you/see)"}, {"before": "No, I", "after": "to her recently. (not/speak)"}, {"before": "He", "after": "to school this week. (not/be)"}, {"before": "I'm sorry. I", "after": "it yet. (not/finish)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ee12b338-86eb-5be7-ae1f-f796d6017e5b',$j${"items": [{"accept": ["has just passed"]}, {"accept": ["have never smelled", "have never smelt"]}, {"accept": ["Have you seen"]}, {"accept": ["haven't spoken", "have not spoken"]}, {"accept": ["hasn't been", "has not been"]}, {"accept": ["haven't finished", "have not finished"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('da588050-62eb-5d3f-84a4-a2844faa867d','88f262f7-05a6-541f-bf84-f169c7510b3d',1,'FILL_BLANK','Составьте предложения в present perfect, используя for или since.',$j${"items": [{"before": "", "after": "(Joe / play / the guitar / 1999)"}, {"before": "", "after": "(Chris / be / ill / a week)"}, {"before": "", "after": "(Jenny / not take / a holiday / years)"}, {"before": "", "after": "(Sam / not be / to school / last Monday)"}, {"before": "", "after": "(They / be / friends / years)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('da588050-62eb-5d3f-84a4-a2844faa867d',$j${"items": [{"accept": ["Joe has played the guitar since 1999"]}, {"accept": ["Chris has been ill for a week"]}, {"accept": ["Jenny hasn't taken a holiday for years", "Jenny has not taken a holiday for years"]}, {"accept": ["Sam hasn't been to school since last Monday", "Sam has not been to school since last Monday"]}, {"accept": ["They have been friends for years"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('e391ae6f-72c5-5e0a-8795-6b1d6f82edd2','88f262f7-05a6-541f-bf84-f169c7510b3d',2,'CHOOSE','Выберите have/has been (to) или have/has gone (to).',$j${"items": [{"before": "My parents", "after": "to London. They are still there.", "options": [{"id": "o1", "label": "have gone"}, {"id": "o2", "label": "have been"}]}, {"before": "We", "after": "to Egypt with our school, but we came back.", "options": [{"id": "o1", "label": "have gone"}, {"id": "o2", "label": "have been"}]}, {"before": "She", "after": "to her grandmother's house for the weekend and she's still there.", "options": [{"id": "o1", "label": "has gone"}, {"id": "o2", "label": "has been"}]}, {"before": "I'd love to visit Wales. I've never", "after": "there.", "options": [{"id": "o1", "label": "gone"}, {"id": "o2", "label": "been"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('e391ae6f-72c5-5e0a-8795-6b1d6f82edd2',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('ddf87f3c-9d1a-5dc5-a2f8-b674096e2085','a0000000-0000-4000-8000-000000000052','Блок 38. Present Perfect vs Past Simple',38,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c9d9b914-9b77-5ecf-afaf-501cbb2968df','ddf87f3c-9d1a-5dc5-a2f8-b674096e2085','Present Perfect vs Past Simple',0,'LESSON',70,$j$[{"type": "rule", "text": "Present perfect: actions at an unstated past time, or actions that started in the past and still continue. Time expressions: for, since, yet, already, ever, never, just, so far."}, {"type": "rule", "text": "Past simple: actions at a stated past time, or actions that started and finished in the past. Time expressions: ago, yesterday, last week/month/year."}, {"type": "examples", "items": ["Kelly has bought a new laptop. (When? We don't know.)", "Jack and Mary went to the amusement park last Saturday.", "We've been friends for ten years."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('14e24e53-60f4-59ae-ab7f-a183049390e1','c9d9b914-9b77-5ecf-afaf-501cbb2968df',0,'FILL_BLANK','Раскройте скобки, употребив present perfect или past simple.',$j${"items": [{"before": "Anna", "after": "skiing for months. (not/go)"}, {"before": "", "after": "a racing car? (you/ever/drive)"}, {"before": "Last week, Sarah", "after": "off her horse. (fall)"}, {"before": "Celia", "after": "playing tennis two years ago. (begin)"}, {"before": "I", "after": "my Geography homework yet. (not/do)"}, {"before": "Jim", "after": "a competition. (never/win)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('14e24e53-60f4-59ae-ab7f-a183049390e1',$j${"items": [{"accept": ["hasn't gone", "has not gone"]}, {"accept": ["Have you ever driven"]}, {"accept": ["fell"]}, {"accept": ["began"]}, {"accept": ["haven't done", "have not done"]}, {"accept": ["has never won"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('5722d379-4b5d-53fc-9d32-77ac9b21a0bf','c9d9b914-9b77-5ecf-afaf-501cbb2968df',1,'FILL_BLANK','Составьте предложения из слов, употребляя present perfect или past simple.',$j${"items": [{"before": "", "after": "(the film / just / finish)"}, {"before": "", "after": "(we / fly / to Saudi Arabia / ten years ago)"}, {"before": "", "after": "(they / never / be / to Australia)"}, {"before": "", "after": "(I / not go / to bed / late / yesterday)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('5722d379-4b5d-53fc-9d32-77ac9b21a0bf',$j${"items": [{"accept": ["The film has just finished"]}, {"accept": ["We flew to Saudi Arabia ten years ago"]}, {"accept": ["They have never been to Australia"]}, {"accept": ["I didn't go to bed late yesterday", "I did not go to bed late yesterday"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('dc0caac7-8da6-561b-98bd-5efa04c66813','c9d9b914-9b77-5ecf-afaf-501cbb2968df',2,'CHOOSE','Выберите правильную форму.',$j${"items": [{"before": "Mr Jackson", "after": "Mount Everest last year.", "options": [{"id": "o1", "label": "climbed"}, {"id": "o2", "label": "has climbed"}]}, {"before": "It", "after": "very hot since Saturday.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "has been"}]}, {"before": "I", "after": "Stuart for a long time!", "options": [{"id": "o1", "label": "didn't see"}, {"id": "o2", "label": "haven't seen"}]}, {"before": "I", "after": "him last week.", "options": [{"id": "o1", "label": "saw"}, {"id": "o2", "label": "have seen"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('dc0caac7-8da6-561b-98bd-5efa04c66813',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('fe39a772-07f8-5135-9110-66febaf9db15','a0000000-0000-4000-8000-000000000052','Блок 39. Question Tags',39,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('6325be91-2a12-5641-a3e1-b8946b335db6','fe39a772-07f8-5135-9110-66febaf9db15','Question Tags',0,'LESSON',70,$j$[{"type": "rule", "text": "Question tags are short questions at the end of a sentence. A positive sentence takes a negative tag, and a negative sentence takes a positive tag. We repeat the auxiliary verb."}, {"type": "rule", "text": "'I am ...' takes the tag 'aren't I?'. Imperatives take 'will you?'. 'Let's ...' takes 'shall we?'."}, {"type": "examples", "items": ["You're new here, aren't you?", "She rarely drinks coffee, does she?", "Don't be late, will you?", "Let's go shopping, shall we?"]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('4f9562f0-6cf0-51d6-9c5d-1958d09854c1','6325be91-2a12-5641-a3e1-b8946b335db6',0,'CHOOSE','Выберите правильный разделительный вопрос.',$j${"items": [{"before": "Your brother has tried bungee jumping before,", "after": "?", "options": [{"id": "o1", "label": "hasn't he"}, {"id": "o2", "label": "didn't he"}]}, {"before": "This is Dr Jenning's surgery,", "after": "?", "options": [{"id": "o1", "label": "isn't it"}, {"id": "o2", "label": "isn't this"}]}, {"before": "Katrina and her mum went shopping,", "after": "?", "options": [{"id": "o1", "label": "did they"}, {"id": "o2", "label": "didn't they"}]}, {"before": "They never eat meat,", "after": "?", "options": [{"id": "o1", "label": "do they"}, {"id": "o2", "label": "don't they"}]}, {"before": "Don't shout,", "after": "?", "options": [{"id": "o1", "label": "will you"}, {"id": "o2", "label": "won't you"}]}, {"before": "There isn't an art gallery near here,", "after": "?", "options": [{"id": "o1", "label": "is there"}, {"id": "o2", "label": "is it"}]}, {"before": "You've got two children,", "after": "?", "options": [{"id": "o1", "label": "don't you"}, {"id": "o2", "label": "haven't you"}]}, {"before": "I'm younger than you,", "after": "?", "options": [{"id": "o1", "label": "aren't I"}, {"id": "o2", "label": "am I not"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('4f9562f0-6cf0-51d6-9c5d-1958d09854c1',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('60e3b1cb-c665-5ef0-a3a3-04328280ed60','6325be91-2a12-5641-a3e1-b8946b335db6',1,'FILL_BLANK','Добавьте разделительный вопрос.',$j${"items": [{"before": "You're fourteen years old,", "after": "?"}, {"before": "They live near the lake,", "after": "?"}, {"before": "You didn't finish your homework,", "after": "?"}, {"before": "Laura's got a new car,", "after": "?"}, {"before": "We won't go shopping today,", "after": "?"}, {"before": "Jane hasn't got a car,", "after": "?"}, {"before": "They never go to the cinema,", "after": "?"}, {"before": "Let's go to the cinema,", "after": "?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('60e3b1cb-c665-5ef0-a3a3-04328280ed60',$j${"items": [{"accept": ["aren't you"]}, {"accept": ["don't they"]}, {"accept": ["did you"]}, {"accept": ["hasn't she"]}, {"accept": ["will we"]}, {"accept": ["has she"]}, {"accept": ["do they"]}, {"accept": ["shall we"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('14d471c8-c547-5b61-8a1d-55ef3e964f2d','6325be91-2a12-5641-a3e1-b8946b335db6',2,'FILL_BLANK','Вставьте правильный разделительный вопрос.',$j${"items": [{"before": "You're new here,", "after": "?"}, {"before": "You haven't seen George this week,", "after": "?"}, {"before": "You will remember to pay the bills today,", "after": "?"}, {"before": "Jo's party is tomorrow,", "after": "?"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('14d471c8-c547-5b61-8a1d-55ef3e964f2d',$j${"items": [{"accept": ["aren't you"]}, {"accept": ["have you"]}, {"accept": ["won't you"]}, {"accept": ["isn't it"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('5846acfc-ce04-5657-9503-0bd39c98ca80','a0000000-0000-4000-8000-000000000052','Блок 40. Countable and Uncountable Nouns',40,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('028b3e9b-4b40-5643-8b1f-5530d7729831','5846acfc-ce04-5657-9503-0bd39c98ca80','Countable and Uncountable Nouns',0,'LESSON',70,$j$[{"type": "rule", "text": "Countable nouns have a singular and a plural form (one pen, two pens). Uncountable nouns cannot be counted and usually have no plural (sugar, milk, money, information, news, furniture)."}, {"type": "rule", "text": "Use a/an with singular countable nouns. Use 'some' in affirmative sentences (and in offers/requests). Use 'any' in negatives and questions."}, {"type": "text", "text": "We use partitives with uncountable nouns: a glass of water, a packet of peanuts, a loaf of bread, a carton of milk, a bar of chocolate."}, {"type": "examples", "items": ["There is a pineapple.", "There are some bananas.", "Are there any grapes?", "There isn't any flour."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('38442f93-3794-504a-a1dc-f5d4a8677a15','028b3e9b-4b40-5643-8b1f-5530d7729831',0,'FILL_BLANK','Вставьте a, an или some.',$j${"items": [{"before": "", "after": "strawberries"}, {"before": "", "after": "tomato"}, {"before": "", "after": "orange"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('38442f93-3794-504a-a1dc-f5d4a8677a15',$j${"items": [{"accept": ["some"]}, {"accept": ["a"]}, {"accept": ["an"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('62606192-cd38-5c74-a8d3-462a30b22116','028b3e9b-4b40-5643-8b1f-5530d7729831',1,'SORT_COLUMNS','Распределите существительные по колонкам.',$j${"columns": [{"id": "c1", "label": "Countable"}, {"id": "c2", "label": "Uncountable"}], "items": [{"id": "i1", "label": "vegetable"}, {"id": "i2", "label": "money"}, {"id": "i3", "label": "water"}, {"id": "i4", "label": "meat"}, {"id": "i5", "label": "grape"}, {"id": "i6", "label": "biscuit"}, {"id": "i7", "label": "cheese"}, {"id": "i8", "label": "egg"}, {"id": "i9", "label": "milk"}, {"id": "i10", "label": "rose"}, {"id": "i11", "label": "rice"}, {"id": "i12", "label": "bread"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('62606192-cd38-5c74-a8d3-462a30b22116',$j${"placement": {"i1": "c1", "i2": "c2", "i3": "c2", "i4": "c2", "i5": "c1", "i6": "c1", "i7": "c2", "i8": "c1", "i9": "c2", "i10": "c1", "i11": "c2", "i12": "c2"}}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('ee1954c9-6100-5a61-a49b-eebe63fe5f9c','028b3e9b-4b40-5643-8b1f-5530d7729831',2,'CHOOSE','Выберите a, an, some или any.',$j${"items": [{"before": "Do you want", "after": "sugar in your coffee?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Are there", "after": "Italian restaurants near here?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "There's", "after": "really nice one at the end of the street.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "some"}]}, {"before": "I had", "after": "bowl of cereal for breakfast.", "options": [{"id": "o1", "label": "a"}, {"id": "o2", "label": "an"}]}, {"before": "Are you going to buy", "after": "butter for the cake?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('ee1954c9-6100-5a61-a49b-eebe63fe5f9c',$j${"items": [{"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('0301f3f0-8ff6-5954-89f1-db3f0397338f','a0000000-0000-4000-8000-000000000052','Блок 41. Some / Any / No / Every + Compounds',41,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('c15ab77c-0060-5e75-b0d1-1e99a1945040','0301f3f0-8ff6-5954-89f1-db3f0397338f','Some / Any / No / Every + Compounds',0,'LESSON',70,$j$[{"type": "rule", "text": "Use 'some' compounds (someone, somebody, something, somewhere) in affirmative sentences and in offers/requests. Use 'any' compounds (anyone, anybody, anything, anywhere) in negatives and questions."}, {"type": "rule", "text": "Use 'no' compounds (no one, nobody, nothing, nowhere) in negative sentences with a positive verb. Use 'every' compounds (everyone, everybody, everything, everywhere) with a singular verb."}, {"type": "examples", "items": ["Someone left the window open.", "There isn't anyone in the room.", "There was nobody I knew at the party.", "Everything is ready."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('0e4048cb-76af-5a08-b969-716af42294dd','c15ab77c-0060-5e75-b0d1-1e99a1945040',0,'CHOOSE','Выберите правильное слово.',$j${"items": [{"before": "Did", "after": "buy a present for Angela's birthday?", "options": [{"id": "o1", "label": "anyone"}, {"id": "o2", "label": "no one"}]}, {"before": "She said", "after": "which really surprised me!", "options": [{"id": "o1", "label": "something"}, {"id": "o2", "label": "nothing"}]}, {"before": "Are you going", "after": "nice this weekend?", "options": [{"id": "o1", "label": "anywhere"}, {"id": "o2", "label": "nowhere"}]}, {"before": "", "after": "just rang the doorbell.", "options": [{"id": "o1", "label": "Someone"}, {"id": "o2", "label": "Anyone"}]}, {"before": "There's", "after": "in the fridge. It's empty.", "options": [{"id": "o1", "label": "nothing"}, {"id": "o2", "label": "anything"}]}, {"before": "There was", "after": "to sit. We went for a pizza instead!", "options": [{"id": "o1", "label": "nowhere"}, {"id": "o2", "label": "somewhere"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('0e4048cb-76af-5a08-b969-716af42294dd',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('8bc3c45a-3719-5a3c-9a3f-5b6ddba9a1b6','c15ab77c-0060-5e75-b0d1-1e99a1945040',1,'FILL_BLANK','Заполните пропуски словами с every (everyone, everything, everywhere, every).',$j${"items": [{"before": "The party was great!", "after": "was wonderful!"}, {"before": "I can't find my glasses. I've looked", "after": "."}, {"before": "I love swimming! I go", "after": "morning."}, {"before": "Is", "after": "here? No, we're still waiting for Terry."}, {"before": "New York was great!", "after": "was very friendly there."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('8bc3c45a-3719-5a3c-9a3f-5b6ddba9a1b6',$j${"items": [{"accept": ["Everything"]}, {"accept": ["everywhere"]}, {"accept": ["every"]}, {"accept": ["everyone", "everybody"]}, {"accept": ["Everyone", "Everybody"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('c45d97b2-43e6-523e-a882-6b14ffa22ec8','c15ab77c-0060-5e75-b0d1-1e99a1945040',2,'FILL_BLANK','Заполните пропуски: something, someone, anything, anywhere или nobody.',$j${"items": [{"before": "Did you hear that? I think", "after": "is at the door!"}, {"before": "Have you seen my green jacket", "after": "?"}, {"before": "I called his house but", "after": "answered."}, {"before": "I'm hungry. I'd like to eat", "after": "."}, {"before": "There isn't", "after": "in the fridge."}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('c45d97b2-43e6-523e-a882-6b14ffa22ec8',$j${"items": [{"accept": ["someone"]}, {"accept": ["anywhere"]}, {"accept": ["nobody"]}, {"accept": ["something"]}, {"accept": ["anything"]}]}$j$::jsonb,'');
INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('2d16c481-193e-5111-a7b2-db2d7ef37655','a0000000-0000-4000-8000-000000000052','Блок 42. Quantifiers (a lot of, much, many, few, little)',42,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('98c70a08-f817-5292-979d-c7ba713c6009','2d16c481-193e-5111-a7b2-db2d7ef37655','Quantifiers (a lot of, much, many, few, little)',0,'LESSON',70,$j$[{"type": "rule", "text": "We normally use a lot of / lots of in positive sentences with plural countable nouns and uncountable nouns. We omit 'of' when a lot / lots is not followed by a noun."}, {"type": "rule", "text": "We normally use much and many in questions and negations. Much goes before uncountable nouns; many goes before plural countable nouns. They can also go after 'too'."}, {"type": "rule", "text": "We use how much + uncountable noun (amount) and how many + countable noun (number)."}, {"type": "rule", "text": "We use a few / few with plural countable nouns and a little / little with uncountable nouns. A few / a little = not many / not much, but enough. Few / little = hardly any / almost none."}, {"type": "examples", "items": ["Pete's got a lot of books.", "There isn't much honey left in the jar.", "How many eggs are there in the fridge?", "I've got a little money. I can buy Nick a present.", "There are few crisps in the bag. It's almost empty."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('23aa2188-b9dd-59e8-95e1-a25530a26862','98c70a08-f817-5292-979d-c7ba713c6009',0,'CHOOSE','Выберите правильный вариант.',$j${"items": [{"before": "There's", "after": "cheese in this pasta.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}, {"id": "o3", "label": "a lot of"}]}, {"before": "How", "after": "tea do you drink in a week?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "a little"}, {"id": "o3", "label": "a lot of"}]}, {"before": "There are", "after": "souvenirs in this shop.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}, {"id": "o3", "label": "a lot of"}]}, {"before": "I like eating bread with", "after": "honey.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}, {"id": "o3", "label": "a lot of"}]}, {"before": "We can't bake bread. We haven't got", "after": "flour.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}, {"id": "o3", "label": "a lot of"}]}, {"before": "There aren't", "after": "people on this bus.", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}, {"id": "o3", "label": "few"}]}]}$j$::jsonb,10);
