INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('968dd843-2230-51de-b07e-ec69d0522d0c','98c70a08-f817-5292-979d-c7ba713c6009',1,'FILL_BLANK','Заполните пропуски словами a lot of, much или many.',$j${"items": [{"before": "There are", "after": "pears in the fruit bowl."}, {"before": "There isn't", "after": "water left in the vase."}, {"before": "Were there", "after": "people at the party?"}, {"before": "We haven't got", "after": "biscuits left."}, {"before": "Is there", "after": "bread in the cupboard?"}, {"before": "Carol hasn't got", "after": "money in her purse."}, {"before": "My dad takes", "after": "sugar in his coffee."}, {"before": "There isn't", "after": "traffic today, so the roads are quiet."}, {"before": "Are there", "after": "children at your school?"}]}$j$::jsonb,10);
