INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('90e76293-04d2-5f17-aa0e-31e31cb31000','98c70a08-f817-5292-979d-c7ba713c6009',2,'CHOOSE','Подчеркните (выберите) правильное слово.',$j${"items": [{"before": "Yes, I'm having", "after": "friends over for dinner.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "You must have added", "after": "sugar.", "options": [{"id": "o1", "label": "too many"}, {"id": "o2", "label": "too much"}]}, {"before": "Have you read", "after": "books?", "options": [{"id": "o1", "label": "much"}, {"id": "o2", "label": "many"}]}, {"before": "We've only got", "after": "cheese left.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "Would you like me to go out and buy", "after": "?", "options": [{"id": "o1", "label": "some"}, {"id": "o2", "label": "any"}]}, {"before": "Could I have", "after": "milk for my coffee, please?", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}, {"before": "We've got", "after": "oranges. We can make some juice.", "options": [{"id": "o1", "label": "a few"}, {"id": "o2", "label": "a little"}]}]}$j$::jsonb,10);
