INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('a6f14be6-8a9c-5f88-8840-4172c948b120','98c70a08-f817-5292-979d-c7ba713c6009',4,'FILL_BLANK','Заполните пропуски выражениями too much или too many.',$j${"items": [{"before": "Don't eat", "after": "chocolate. It's bad for your teeth."}, {"before": "That coat costs", "after": "money. I can't afford it."}, {"before": "There were", "after": "people in the supermarket."}, {"before": "You've put", "after": "milk in my coffee."}, {"before": "There are", "after": "flowers in this vase."}, {"before": "There's", "after": "noise in this house. I'll go study at the library."}]}$j$::jsonb,10);
