INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('ef6089a0-7b69-5c90-92e7-a514a6dd4428','a0000000-0000-4000-8000-000000000052','Блок 43. The Passive (present simple, past simple)',43,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('908c6ff8-9461-597c-9160-e0de58f1dec4','ef6089a0-7b69-5c90-92e7-a514a6dd4428','The Passive (present simple, past simple)',0,'LESSON',70,$j$[{"type": "rule", "text": "We form the passive with the verb 'to be' in the appropriate tense and the past participle of the main verb."}, {"type": "rule", "text": "The object of the active sentence becomes the subject of the passive. The subject of the active becomes the agent, introduced with 'by' + person or 'with' + object/instrument."}, {"type": "rule", "text": "We use the passive when the agent is unknown, unimportant or obvious, to be more polite/formal, when the action is more important than the agent, or to put emphasis on the agent."}, {"type": "examples", "items": ["The TV was invented by John Baird.", "Barcelona is visited by a lot of tourists every year.", "100 people are employed by the company.", "The robbers were arrested last Monday.", "Penicillin was discovered by Alexander Fleming."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('813cacea-df05-55a5-a180-6f31c75c54d9','908c6ff8-9461-597c-9160-e0de58f1dec4',0,'CHOOSE','Выберите правильную форму глагола to be.',$j${"items": [{"before": "The new stadium", "after": "opened last weekend.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "is"}]}, {"before": "The Eiffel Tower", "after": "visited by thousands of tourists every day.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "was"}]}, {"before": "The mayor", "after": "driven to the airport yesterday.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "is"}]}, {"before": "French and Spanish", "after": "taught at my school.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "are"}]}, {"before": "Romeo & Juliet", "after": "written by Shakespeare.", "options": [{"id": "o1", "label": "is"}, {"id": "o2", "label": "was"}]}, {"before": "The Empire State Building", "after": "built in 1931.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "were"}]}, {"before": "Australia", "after": "discovered by Captain Cook.", "options": [{"id": "o1", "label": "was"}, {"id": "o2", "label": "is"}]}, {"before": "Twenty people", "after": "killed in the plane crash last Monday.", "options": [{"id": "o1", "label": "are"}, {"id": "o2", "label": "were"}]}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('813cacea-df05-55a5-a180-6f31c75c54d9',$j${"items": [{"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}, {"correctId": "o2"}, {"correctId": "o1"}, {"correctId": "o1"}, {"correctId": "o2"}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('179aa7b3-2005-5ca8-a602-83f2f40e8637','908c6ff8-9461-597c-9160-e0de58f1dec4',1,'FILL_BLANK','Заполните пропуски формой is, are, was или were.',$j${"items": [{"before": "Feta cheese", "after": "made in Greece."}, {"before": "I didn't fly to India because all the flights", "after": "cancelled."}, {"before": "The trains", "after": "cleaned every night."}, {"before": "Many buildings", "after": "destroyed in the earthquake."}, {"before": "This cake", "after": "made with cream."}, {"before": "Barcelona", "after": "visited by a lot of tourists every year."}, {"before": "Dinner", "after": "served at 9 o'clock last night."}, {"before": "Hundreds of books", "after": "borrowed from the library every day."}, {"before": "A lot of new shops", "after": "opened in the city centre last year."}]}$j$::jsonb,10);
