INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('917776cd-edc2-5e26-a42f-99ebafce4444','908c6ff8-9461-597c-9160-e0de58f1dec4',2,'CHOOSE','Заполните пропуски предлогом by или with.',$j${"items": [{"before": "The skyscraper was built", "after": "two hundred workers.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}, {"before": "A pizza is topped", "after": "tomato sauce and cheese.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}, {"before": "That picture was painted", "after": "oil paints.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}, {"before": "The library was broken into", "after": "three men.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}, {"before": "The tickets were paid for", "after": "my dad's credit card.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}, {"before": "This song was written", "after": "my uncle.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}, {"before": "The room was decorated", "after": "colourful balloons.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}, {"before": "The bank was robbed", "after": "two men dressed in black.", "options": [{"id": "o1", "label": "by"}, {"id": "o2", "label": "with"}]}]}$j$::jsonb,10);
