INSERT INTO "Module" (id,"bookId",title,"order","pageCount") VALUES ('79559493-0c5d-59cf-9e29-bcb4b2200045','a0000000-0000-4000-8000-000000000052','Блок 45. Revision of Tenses',45,0);
INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('cf921886-802a-5a3f-bc4a-4a25cd0a5695','79559493-0c5d-59cf-9e29-bcb4b2200045','Revision of Tenses',0,'LESSON',70,$j$[{"type": "rule", "text": "Present Simple: habits and routines. Present Continuous: actions happening now or around now."}, {"type": "rule", "text": "Past Simple: completed actions in the past. Past Continuous: actions in progress at a moment in the past, often interrupted by a Past Simple action."}, {"type": "rule", "text": "Future: 'will' for predictions/decisions at the moment of speaking, 'be going to' for intentions/plans, Present Continuous for fixed arrangements."}, {"type": "examples", "items": ["Diane lives in Berlin.", "My dad is washing his car at the moment.", "Tom was playing computer games when the phone rang.", "They are travelling to Rome next week.", "We went for a picnic last week."]}]$j$::jsonb);
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('df94ca84-b095-5aaf-b5b4-fa4d47de0a80','cf921886-802a-5a3f-bc4a-4a25cd0a5695',0,'FILL_BLANK','Поставьте глагол в скобках в Present Simple или Present Continuous.',$j${"items": [{"before": "Diane", "after": "in Berlin. (live)"}, {"before": "John", "after": "his room every Saturday. (tidy)"}, {"before": "My dad", "after": "his car at the moment. (wash)"}, {"before": "I always", "after": "before I go to bed. (read)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('df94ca84-b095-5aaf-b5b4-fa4d47de0a80',$j${"items": [{"accept": ["lives"]}, {"accept": ["tidies"]}, {"accept": ["is washing"]}, {"accept": ["read"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('9d8f7c68-8f78-5f66-9751-9582639cef35','cf921886-802a-5a3f-bc4a-4a25cd0a5695',1,'FILL_BLANK','Поставьте глагол в скобках в Past Simple.',$j${"items": [{"before": "I", "after": "down the stairs yesterday morning. (fall)"}, {"before": "John and Mary", "after": "on holiday to Italy last week. (go)"}, {"before": "My mum", "after": "a pizza for our lunch yesterday. (make)"}, {"before": "Carole", "after": "a new dress two days ago. (buy)"}, {"before": "Jim", "after": "for his exams last weekend. (study)"}, {"before": "The children", "after": "the bus to school last Friday. (catch)"}]}$j$::jsonb,10);
INSERT INTO "LessonExerciseAnswer" ("exerciseId","answerKey",explanation) VALUES ('9d8f7c68-8f78-5f66-9751-9582639cef35',$j${"items": [{"accept": ["fell"]}, {"accept": ["went"]}, {"accept": ["made"]}, {"accept": ["bought"]}, {"accept": ["studied"]}, {"accept": ["caught"]}]}$j$::jsonb,'');
INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('794f79b7-184e-5d57-a979-b7f485e8b87c','cf921886-802a-5a3f-bc4a-4a25cd0a5695',2,'CHOOSE','Выберите правильную форму (Past Simple или Past Continuous).',$j${"items": [{"before": "Tom", "after": "computer games when the phone rang.", "options": [{"id": "o1", "label": "was playing"}, {"id": "o2", "label": "played"}]}, {"before": "Tom", "after": "to Turkey last summer.", "options": [{"id": "o1", "label": "flew"}, {"id": "o2", "label": "was flying"}]}, {"before": "At 3 o'clock yesterday afternoon, Sue", "after": "home from school.", "options": [{"id": "o1", "label": "walked"}, {"id": "o2", "label": "was walking"}]}, {"before": "Dave", "after": "when he slipped on a banana skin.", "options": [{"id": "o1", "label": "was jogging"}, {"id": "o2", "label": "jogged"}]}]}$j$::jsonb,10);
