INSERT INTO "LessonExercise" (id,"unitId","orderIndex",type,instruction,content,xp) VALUES ('75730987-422b-584d-863c-ca12b24aa3bb','cf921886-802a-5a3f-bc4a-4a25cd0a5695',3,'CHOOSE','Выберите правильную форму будущего времени.',$j${"items": [{"before": "I'm afraid I", "after": "be able to come to your party.", "options": [{"id": "o1", "label": "will"}, {"id": "o2", "label": "won't"}]}, {"before": "They", "after": "to Rome next week.", "options": [{"id": "o1", "label": "travelled"}, {"id": "o2", "label": "are travelling"}]}, {"before": "I'll call you when I", "after": "at the airport.", "options": [{"id": "o1", "label": "arrive"}, {"id": "o2", "label": "will arrive"}]}, {"before": "We", "after": "to the supermarket three times last week.", "options": [{"id": "o1", "label": "went"}, {"id": "o2", "label": "were going"}]}]}$j$::jsonb,10);
