INSERT INTO "LessonUnit" (id,"moduleId",title,"orderIndex",kind,"passThreshold",intro) VALUES ('84d23f88-75c2-5aba-a0ca-15f58bee3bca','cce27229-cbcf-529d-8110-1f84ac9c9434','Irregular Verbs',0,'LESSON',70,$j$[{"type": "text", "text": "English irregular verbs do not form the Past Simple and Past Participle with -ed. You must learn each form by heart."}, {"type": "rule", "text": "Each verb has three forms: Infinitive - Past Simple - Past Participle (e.g. go - went - gone; write - wrote - written)."}, {"type": "examples", "items": ["go - went - gone", "see - saw - seen", "buy - bought - bought", "write - wrote - written", "take - took - taken"]}]$j$::jsonb);
